COLLDATA("tadabburar","ar",[[484,"§الشورىٰ\nwords\nفَاطِرُخَالِقُ، وَمُبدِعُ.\nيَذرَؤُكُم فِيهِيُكَثِّرُكُم؛ بِسَبَبِ التَّزوِيجِ.\nمَقَالِيدُ السَّمَاوَاتِمِلكُهَا، وَمَفَاتِيحُ خَزَائِنِهَا.\nيَبسُطُيُوسِعُ.\nوَيَقدِرُيُضَيِّقُ.\nيَجتَبِي إِلَيهِيَصطَفِي لِتَوحِيدِهِ، وَدِينِهِ.\nيُنِيبُيَرجِعُ إِلَيهِ بِالطَّاعَةِ.\nمُرِيبٍمُوقِعٍ فِي الرِّيبَةِ، وَالاِختِلاَفِ المَذمُومِ.\ndeeds\nادع صديقًا أو قريبًا إلى عبادةٍ أو سنةٍ أنت تعملها.\nقل هذه العبارة اتباعًا لأوامر الله -سبحانه وتعالى-.\nانظر بدعة أو معصية انتشرت فيمن حولك وابتعد عنها، وحذر منها.\nguid\nإثبات الصفات لله سبحانه ونفي مماثلته للمخلوقات.\nارض بما قسم الله؛ فالذي يبسط الرزق ويقبضه هو الله وحده.\nحسن مقصد العبد مع اجتهاده في طلب الهداية من أسباب التيسير لها.\nrefl\n۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ\nهذه أكبر مِنَّةٍ أنعم الله بها على عباده؛ أن شرع لهم من الدين خير الأديان وأفضلها، وأزكاها وأطهرها؛ دين الإسلام الذي شرعه الله للمصطفين المختارين من عباده، بل شرعه الله لخيار الخيار، وصفوة الصفوة؛ وهم أولو العزم من المرسلين المذكورون في هذه الآية؛ أعلى الخلق درجة، وأكملهم من كل وجه. السعدي:٧٥٤.\nما أعظم نعمة أنعم الله بها عليك؟\n۞شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ\nاتفق دين سيدنا محمد -صلى الله عليه وسلم- مع جميع الأنبياء في أصول الاعتقادات؛ وذلك هو المراد هنا، ولذلك فسره بقوله: ﴿أَنۡ أَقِيمُواْ ٱلدِّينَ﴾: يعني إقامة الإسلام الذي هو توحيد الله وطاعته، والإيمان برسله وكتبه وبالدار الآخرة، وأمَّا الأحكام الفروعية؛ فاختلفت فيها الشرائع، فليست تراد هنا. ابن جزي:٢/٢٩٩.\nما الأمور التي اتفقت فيها رسالات الأنبياء؟ وما الأمور التي اختلفت فيها؟\nأَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ\nبعث الله الأنبياء كلهم بإقامة الدين، والألفة والجماعة، وترك الفرقة والمخالفة. البغوي:٤/٧٧.\nما السمة الجامعة المستفادة من الآية التي بعث الله تعالى بها جميع الأنبياء؟\nكَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ\nأي: عظُم عليهم ﴿مَا تَدۡعُوهُمۡ إِلَيۡهِۚ﴾ من التوحيد ورفض الأوثان. قال قتادة: \"﴿كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ﴾؛ فاشتد عليهم شهادة أن لا إله إلا الله، وضاق بها إبليس وجنوده؛ فأبى الله -عز وجل- إلا أن ينصرها ويعليها ويظهرها على من ناوأها\". القرطبي:١٨/٤٥٣.\nما الأمر الذي عظم على المشركين؟\nوَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ\nبغيًا من بعضهم على بعض طلبًا للرياسة؛ فليس تفرقهم لقصور في البيان والحجج، ولكن للبغي والظلم والاشتغال بالدنيا. القرطبي:١٨/٤٥٤.\nما سبب تفرق بعض وجهاء المسلمين رغم وجود العلم؟\nوَمَا تَفَرَّقُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ\nلما أمر تعالى باجتماع المسلمين على دينهم، ونهاهم عن التفرق، أخبرهم أنكم لا تغتروا بما أنزل الله عليكم من الكتاب؛ فإن أهل الكتاب لم يتفرقوا حتى أنزل الله عليهم الكتاب الموجب للاجتماع. السعدي:٧٥٥.\nما الفائدة التي نخرج بها من هذا الإخبار عن أهل الكتب السابقة؟\nوَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡۖ\nولم يقل: \"ولا تتبع دينهم\"؛ لأن حقيقة دينهم الذي شرعه الله لهم هو دين الرسل كلهم، ولكنهم لم يتبعوه، بل اتبعوا أهواءهم، واتخذوا دينهم لهوًا ولعبًا. السعدي:٧٥٥.\nفي الآية تنبيه على خطورة البدعة، بينه."],[485,"§الشورىٰ\nwords\nيُحَآجُّونَ فِي اللهِيُخَاصِمُونَ فِي دِينِ اللهِ.\nدَاحِضَةٌذَاهِبَةٌ بَاطِلَةٌ.\nمُشفِقُونَ مِنهَاخَائِفُونَ مِن قِيَامِهَا.\nيُمَارُونَيُجَادِلُونَ.\nحَرثَ الآخِرَةِثَوَابَهَا.\nكَلِمَةُ الفَصلِقَضَاؤُهُ بِإِمهَالِهِم وَعَدَمِ مُعَاجَلَتِهِم بِالعُقُوبَةِ.\ndeeds\nاعمل عملًا يدل على إيمانك بقرب الساعة.\nتفكر في نفسك وسجل ثلاثة مظاهر للطف الله تعالى بك.\nاغرس في قلبك أمنية لعمل صالح عظيم، واجتهد في تحقيقها حتى يزيدك الله أعمالًا صالحة أخرى.\nguid\nبيان بعض الحكمة في إنزال الكتاب -أي القرآن- والميزان؛ وهو أن يحكم الناس بالقسط.\nبيان وجوب إصلاح النيات؛ فإن مدار العمل قبولًا ورفضًا بحسبها.\nاحذر من البدع؛ فإنها من أسباب انحراف الديانات السابقة، وتجلب غضب الله، ولذلك تجد الشيطان لا يخذّل العبد عنها.\nrefl\nٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ وَمَا يُدۡرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٞ ١٧\nفإن قيل: ما وجه اتصال ذكر الكتاب والميزان بذكر الساعة؟ فالجواب: أن الساعة يوم الجزاء والحساب؛ فكأنه قال: اعدلوا وافعلوا الصواب قبل اليوم الذي تحاسبون فيه على أعمالكم. ابن جزي:٢/٣٠٠.\nما وجه ذكر الساعة بعد الكتاب والميزان؟\nيَسۡتَعۡجِلُ بِهَا ٱلَّذِينَ لَا يُؤۡمِنُونَ بِهَاۖ وَٱلَّذِينَ ءَامَنُواْ مُشۡفِقُونَ مِنۡهَا\nأي: خائفون لإيمانهم بها، وعلمهم بما تشتمل عليه من الجزاء بالأعمال، وخوفهم لمعرفتهم بربهم أن لا تكون أعمالهم منجية لهم ولا مسعدة. السعدي:٧٥٦.\nما سبب خوف المؤمنين من الساعة؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ\nومن لطفه أن قيَّض لعبده كل سبب يعوقه ويحول بينه وبين المعاصي، حتى إنه تعالى إذا علم أن الدنيا والمال والرياسة -ونحوها مما يتنافس فيه أهل الدنيا- تقطع عبده عن طاعته، أو تحمله على الغفلة عنه، أو على معصيةٍ؛ صرفها عنه، وقَدَر عليه رزقه، ولهذا قال هنا: ﴿يَرۡزُقُ مَن يَشَآءُ﴾. السعدي:٧٥٧.\nلماذا ذكر الرزق بعد اللطف بعباده؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ١٩\nوعُطف ﴿وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ﴾ على صفة (لطيف) أو على جملة ﴿يَرۡزُقُ مَن يَشَآءُ﴾، وهو تمجيد لله تعالى بهاتين الصفتين، ويفيد الاحتراس من توهم أن لطفه عن عجز أو مصانعة؛ فإنه قوي عزيز لا يَعجز ولا يصانِع، أو عن توهم أن رزقه لمن يشاء عن شحّ أو قِلّةٍ؛ فإنه القويّ، والقوي تنتفي عنه أسباب الشحّ، والعزيز ينتفي عنه سبب الفقر؛ فرزقه لمن يشاء بما يشاء منوط لحكمة عَلِمها في أحوال خلقه عامة وخاصة. ابن عاشور:٢٥/٧٣.\nما فائدة عطف ﴿وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ﴾ على صفة (لطيف)؟\nٱللَّهُ لَطِيفُۢ بِعِبَادِهِۦ يَرۡزُقُ مَن يَشَآءُۖ وَهُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ ١٩\nقال محمد بن علي الكتاني: \"اللطيف بمن لجأ إليه من عباده إذا يئس من الخلق وتوكل عليه ورجع إليه، فحينئذ يقبله ويقبل عليه\"... وقيل: اللطيف الذي ينشر من عباده المناقب ويستر عليهم المثالب. وقيل: هو الذي يقبل القليل ويبذل الجزيل. وقيل: هو الذي يجبر الكسير وييسر العسير... وقيل: هو الذي لا يعاجل من عصاه ولا يخيب من رجاه. وقيل: هو الذي لا يرد سائله ولا يوئس آمله. وقيل: هو الذي يعفو عمن يهفو. وقيل: هو الذي يرحم من لا يَرحَم نفسه. القرطبي:١٨/٤٥٩-٤٦١.\nماذا تعرف عن حقيقة لطف الله تعالى بعبده ؟\nمَن كَانَ يُرِيدُ حَرۡثَ ٱلۡأٓخِرَةِ نَزِدۡ لَهُۥ فِي حَرۡثِهِۦۖ\nالمعنى: أي من طلب بما رزقناه حرثًا لآخرته، فأدى حقوق الله، وأنفق في إعزاز الدين؛ فإنما نعطيه ثواب ذلك للواحد عشرًا إلى سبعمائة فأكثر. القرطبي:١٨/٤٦١.\nما المقصود بالزيادة في الحرث ؟\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ ٢٢\nمن لطائف هذا الوجه أنه جاء على الترتيب المعهود في الحصول في الخارج؛ فإن الضيف أو الوافد ينزل أول قدومه في منزل إكرام، ثم يحضر إليه القِرى، ثم يخالطه رب المنزل ويقترب منه. ابن عاشور: ٢٥/٧٩.\nجاءت الآية الكريمة بثلاث مراتب للمؤمنين في الجنة هي مراتب الإكرام، بيِّنها؟"],[486,"§الشورىٰ\nwords\nإِلاَّ المَوَدَّةَ فِي القُربَىلاَ تُؤذُونِي فِي تَبلِيغِ الدَّعوَةِ؛ لِمَا بَينِي وَبَينَكُم مِنَ القَرَابَةِ.\nيَقتَرِف حَسَنَةًيَكتَسِب طَاعَةً.\nافتَرَىاختَلَقَ.\nقَنَطُوايَئِسُوا مِن نُزُولِهِ.\nوَيَنشُرُ رَحمَتَهُيَبسُطُ مَطَرَهُ.\nبَثَّفَرَّقَ، وَنَشَرَ.\nدَآبَّةٍمَا يَدُبُّ عَلَى الأَرضِ؛ مِن إِنسٍ، وَحَيَوَانٍ، وَغَيرِهِمَا.\ndeeds\nقل: \"اللهم اقبل توبتي واعف عن سيئاتي\".\nانظر أمرًا أمر الله به ورد في الآيات واستجب له حتى يزيدك الله من فضله.\nتذكر مصيبةً وقعت لك ثم أكثر من الاستغفار مستحضرًا قوله تعالى.\nguid\nوعد الله بمحو الباطل.\nحكمة الله سبحانه في قسمة الأرزاق بين الخلق.\nمن مظاهر رحمة الله بخلقه نزول المطر، وهي نعمة تستوجب الشكر.\nrefl\nذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ\nيقول تعالى لمَّا ذكر روضات الجنات لعباده الذين آمنوا وعملوا الصالحات: ﴿ذَٰلِكَ ٱلَّذِي يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِۗ﴾ أي: هذا حاصل لهم كائن لا محالة؛ ببشارة الله تعالى لهم به. ابن كثير:٤/١١٤.\nما وجه البشارة للمؤمنين في هذه الآية؟\nوَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ٢٥\nلما كانت التوبة من الأعمال العظيمة التي قد تكون كاملة بسبب تمام الإخلاص والصدق فيها، وقد تكون ناقصة عند نقصهما، وقد تكون فاسدة إذا كان القصد منها بلوغ غرض من الأغراض الدنيوية، وكان محل ذلك القلب الذي لا يعلمه إلا الله؛ ختم هذه الآية بقوله ﴿وَيَعۡلَمُ مَا تَفۡعَلُونَ﴾. السعدي:٧٥٨.\nلماذا ختمت الآية بقوله تعالى: ﴿وَيَعۡلَمُ مَا تَفۡعَلُونَ﴾؟\nوَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَيَعۡفُواْ عَنِ ٱلسَّيِّـَٔاتِ وَيَعۡلَمُ مَا تَفۡعَلُونَ ٢٥\nوفي ذكر اسم العباد دون نحو: الناس أو التائبين أو غير ذلك؛ إيماء إلى أن الله رفيق بعباده لمقام العبودية؛ فإن الخالق والصانع يحب صلاح مصنوعه. ابن عاشور:٢٥/٩٠.\nما فائدة التعبير بالعباد دون الناس أو التائبين في الآية الكريمة؟\n۞وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡاْ فِي ٱلۡأَرۡضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٖ مَّا يَشَآءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرُۢ بَصِيرٞ ٢٧\nقد يعلم من حال عبد أنه لو بسط عليه قاده ذلك إلى الفساد فيزوي عنه الدنيا مصلحة له؛ فليس ضيق الرزق هوانًا ولا سعته فضيلةً... وروي: \"إن من عبادي المؤمنين من يسألني الباب من العبادة وإني عليم أن لو أعطيته إياه لدخله العجب فأفسده. وإن من عبادي المؤمنين من لا يصلحه إلا الغنى، ولو أفقرته لأفسده الفقر. وإن من عبادي المؤمنين من لا يصلحه إلا الفقر، ولو أغنيته لأفسده الغنى\". القرطبي:١٨/٤٧٥.\nهل سعة الرزق خير للإنسان على كل حال؟\nوَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ٢٨\nوخصها بالذكر دون غيرها من النعم الدنيوية؛ لأنها نعمة لا يختلف الناس فيها، لأنها أصل دوام الحياة بإيجاد الغذاء الصالح للناس والدواب. ابن عاشور:٢٥/٩٥.\nلماذا خص الغيث بالذكر بعد الرزق العام؟\nوَهُوَ ٱلَّذِي يُنَزِّلُ ٱلۡغَيۡثَ مِنۢ بَعۡدِ مَا قَنَطُواْ وَيَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِيُّ ٱلۡحَمِيدُ ٢٨\nوذكر صفتي ﴿ٱلۡوَلِيُّ ٱلۡحَمِيدُ﴾ دون غيرهما لمناسبتهما للإغاثة؛ لأن (الولي) يحسن إلى مواليه، و (الحميد) يعطي ما يُحمد عليه. ابن عاشور:٢٥/٩٦.\nمن أنسب الأسماء الحسنى في هذا الموضع ﴿ٱلۡوَلِيُّ ٱلۡحَمِيدُ﴾ بين ذلك.\nوَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٖ فَبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُواْ عَن كَثِيرٖ ٣٠\nالمعنى: أن المصائب التي تصيب الناس في أنفسهم وأموالهم إنَّما هي بسبب الذنوب. ابن جزي:٢/٣٠٣.\nما رأيك فيمن يقول: إن سبب الكوارث أسباب طبيعية، والذنوب والمعاصي لا دخل لها بذلك؟"],[487,"§الشورىٰ\nwords\nالجَوَارِالسُّفُنُ الجَارِيَةُ.\nكَالأَعلاَمِكَالجِبَالِ فِي عِظَمِهَا.\nرَوَاكِدَثَوَابِتَ لاَ تَجرِي.\nيُوبِقهُنَّيُهلِكِ السُّفُنَ بِالغَرَقِ.\nمَحِيصٍمَهرَبٍ، وَمَلجَأٍ.\nالبَغيُالظُّلمُ، وَالعُدوَانُ.\nعَزمِ الأُمُورِالأَفعَالِ الحَمِيدَةِ، وَالخِصَالِ المَشكُورَةِ.\ndeeds\nشاهد السفن كيف تمشي في البحر -أو صورة لها-، واكتب تأملاتك لتحقق التفكر في هذه الآية.\nإذا أذّن المؤذّن فاترك ما يشغلك وقم مباشرة إلى المسجد.\nشاور زميلك في أحسن طريقة لحفظ سورة من القرآن الكريم.\nguid\nالحذر من كبائر الذنوب.\nعِظَم منزلة العفو؛ حيث جُعِل أجره على الله.\nالهداية والضلال بيد الله؛ فاسأل الله أن يثبتك على دينه.\nrefl\nوَمِنۡ ءَايَٰتِهِ ٱلۡجَوَارِ فِي ٱلۡبَحۡرِ كَٱلۡأَعۡلَٰمِ ٣٢ إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ ٣٣\nوجُعل ذلك آيةً ﴿لِّكُلِّ صَبَّارٍ شَكُورٍ﴾؛ لأن في الحالتين خوفًا ونجاة، والخوف يدعو إلى الصبر، والنجاةُ تدعو إلى الشكر. ابن عاشور:٢٥/١٠٦.\nلماذا جعل في جري الفلك أو ركودها على ظهر البحر آية لكل صبار شكور؟\nوَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ ٣٧ وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ ٣٩\nإن كلًا من الوصفين في محل, وهو فيه محمود؛ فالعفو عن العاجز المعترف بجرمه محمود, ولفظ المغفرة مُشْعِرٌ به. والانتصار من المُخَاصِم المُصِرّ محمود، ولفظ الانتصار مشعر به. ولو أوقعا على عكس ذلك كانا مذمومين, وعلى هذا جاء قوله: إذا أنـت أكرمت الكريـم ملكتـه * وإن أنـت أكـرمـت اللئيم تمردا... فوضع الندى في موضع السيف بالعلا * مضرّ كوضع السيف في موضع الندى. الألوسي:٢٥/٦٦.\nكيف نجمع بين قول الله تعالى: ﴿وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ﴾ وقوله: ﴿وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلۡبَغۡيُ هُمۡ يَنتَصِرُونَ﴾؟\nوَٱلَّذِينَ ٱسۡتَجَابُواْ لِرَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ ٣٨\nومن الاستجابة لله: إقامة الصلاة، وإيتاء الزكاة؛ فلذلك عطفهما على ذلك؛ من باب عطف الخاص على العام، الدالّ على شرفه وفضله. السعدي:٧٦٠.\nإقامة الصلاة وإيتاء الزكاة داخلة ضمن الاستجابة للرب؛ فلماذا ذكرها بعد ذكر الاستجابة؟\nوَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ\nأي: لا يستبد أحد منهم برأيه في أمر من الأمور المشتركة بينهم، وهذا لا يكون إلا فرعًا عن اجتماعهم وتوالفهم وتواددهم وتحاببهم وكمال عقولهم؛ أنهم إذا أرادوا أمرًا من الأمور التي تحتاج إلى إعمال الفكر والرأي فيها اجتمعوا لها وتشاوروا وبحثوا فيها، حتى إذا تبينت لهم المصلحة انتهزوها وبادروها. السعدي:٧٦٠.\nالشورى بين المسلمين تدل على أمرٍ آخر عظيم، ما هو؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ\nشرط الله في العفو الإصلاح فيه؛ ليدل ذلك على أنه إذا كان الجاني لا يليق العفو عنه، وكانت المصلحة الشرعية تقتضي عقوبته، فإنه في هذه الحال لا يكون مأمورًا به. السعدي: ٧٦٠.\nما وجه ذكر الإصلاح بعد العفو؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ\nفي جعل أجر العافي على الله ما يهيج على العفو، وأن يعامل العبد الخلق بما يحب أن يعامله الله به؛ فكما يحب أن يعفو الله عنه فليعف عنهم، وكما يحب أن يسامحه الله فليسامحهم؛ فإن الجزاء من جنس العمل. السعدي:٧٦٠.\nماذا تستفيد من جعل أجر العافـي على الله؟\nوَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ ٤٠ وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ ٤١\n﴿فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ﴾: هذا يدل على أن العفو عن الظَّلَمة أفضل من الانتصار؛ لأنه ضمن الأجر في العفو، وذَكَرَ الانتصار بلفظ الإباحة في قوله: ﴿وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ﴾. ابن جزي:٢/٣٠٥.\nكيف كان العفو أفضل من الانتصار؟"],[488,"§الشورىٰ\nwords\nيَنظُرُونَ مِن طَرفٍ خَفِيٍّيُسَارِقُونَ النَّظَرَ، وَلاَ يَنظُرُونَ بِمِلءِ أَعيُنِهِم.\nلا مَرَدَّ لَهُلاَ يُمكِنُ رَدُّهُ.\nنَكِيرٍلاَ تُنكِرُونَ ذُنُوبَكُم، وَلَيسَ لَكُم مَكَانٌ تَستَخفُونَ وَتَتَنَكَّرُونَ فِيهِ.\nعَقِيمًالاَ يُولَدُ لَهُ.\nمِن وَرَاءِ حِجَابٍكَمَا كَلَّمَ مُوسَى -عليه السلام-.\ndeeds\nاستجب لكل أمر أمرك به الله تعالى من فعل أو ترك.\nانصح أهلك وادع الله لهم ولنفسك بالهداية.\nانظر أمرًا أمرتك به آية أو حديث كنت مترددًا في تطبيقه، وسارع في الاستجابة له.\nguid\nما أعظم خسائر الظالم يوم القيامة.\nمهمة الرسل التبيلغ والدعوة.\nحكمة الله تعالى وعلمه فيما يهب للعباد من الذرية.\nrefl\nوَتَرَىٰهُمۡ يُعۡرَضُونَ عَلَيۡهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ\nأي: الذل قد اعتراهم بما أسلفوا من عصيان الله تعالى. ابن كثير:٤/١٢٢.\nما سبب ذلهم يوم القيامة ؟\nوَقَالَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِي عَذَابٖ مُّقِيمٖ ٤٥\nأما خسرانهم لأنفسهم فلكونهم صاروا في النار معذبين بها، وأمَّا خسرانهم لأهليهم فلأنهم إن كانوا معهم في النار فلا ينتفعون بهم، وإن كانوا في الجنة فقد حيل بينهم وبينهم. الشوكاني:٤/٥٤٣.\nبيّن كيفية خسران النفس والأهل يوم القيامة؟\nٱسۡتَجِيبُواْ لِرَبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإٖ يَوۡمَئِذٖ وَمَا لَكُم مِّن نَّكِيرٖ ٤٧\nهذه الآية ونحوها فيها ذم الأمل، والأمر بانتهاز الفرصة في كل عمل يعرض للعبد؛ فإن للتأخير آفات. السعدي:٧٦١.\nما الأمل المذموم؟ وهل يسوغ تأخير العمل؟\nفَإِنۡ أَعۡرَضُواْ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظًاۖ\nأي حافظًا لأعمالهم حتى تحاسبهم عليها، وقيل: موكلًا بهم لا تفارقهم دون أن يؤمنوا، أي: ليس لك إكراههم على الإيمان. القرطبي:١٨/٥٠٠.\nفي الآية تسلية للدعاة عند عدم الاستجابة لهم، وضح ذلك.\nوَإِنَّآ إِذَآ أَذَقۡنَا ٱلۡإِنسَٰنَ مِنَّا رَحۡمَةٗ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ٤٨\nوفيه إشارة إلى أنَّ إذاقة الرحمة ليست للفرح والبطر، بل للشكر لموليها. وإصابة المِحنة ليست للكفران والجزع، بل للرجوع إلى مُبلِيها. الألوسي:٢٥/٧٥.\nما الواجب على المؤمن أن يفعله في حال الرخاء، وفي حال الشِدَّة؟\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِنَّ ٱلۡإِنسَٰنَ كَفُورٞ ٤٨\nأي: يجحد ما تقدم من النعم، ولا يعرف إلا الساعة الراهنة. ابن كثير:٤/١٢٢-١٢٣.\nما الفرق بين المسلم والكافر في النظر إلى النعم السابقة؟\nلِّلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَخۡلُقُ مَا يَشَآءُۚ يَهَبُ لِمَن يَشَآءُ إِنَٰثٗا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ ٤٩\nوقيل: قَدَّمَ الإناث توصية برعايتهنَّ لضعفهنَّ؛ لا سيما وكانوا قريبي العهد بالوأد؛ وفي الحديث: \"من ابتُلِيَ بشيء من هذه البنات فأحسن إليهنَّ كنَّ له سترًا من النار\". الألوسي: ٢/٧٥-٧٦.\nبيّن تكريم الإسلام للمرأة وحفظه لها من خلال الآية والحديث."],[489,"§الشورىٰ ، الزخرف\nwords\nرُوحًاقُرآنًا سُمِّيَ القُرآنُ رُوحًا؛ لأَنَّهُ حَيَاةُ القُلُوبِ.\nصِرَاطٍ مُستَقِيمٍهُوَ: الإِسلاَمُ.\nتَصِيرُتَرجِعُ إِلَيهِ، فَيُجَازِيكُم عَلَيهَا.\nأُمِّ الكِتَابِاللَّوحِ المَحفُوظِ.\nأَفَنَضرِبُ عَنكُمُ الذِّكرَ صَفحًاأَفَنُعرِضُ عَنكُم، وَنَترُكُ تَذكِيرَكُم بِالقُرآنِ؟!\ndeeds\nسَجِّل ثلاث فوائد دنيوية أو أخروية أحياها فيك تدبرك للقرآن.\nتخيل أن القرآن لم يصل إليك، وأنك لم تهتد إلى الإسلام؛ فكم هي الضيقة والشقاء التي ستعيش بها، ثم احمد الله على نعمة الهداية والإيمان.\nاكتب مقالة أو ألقِ كلمة لإخوانك عن فضل الأنبياء وعظمتهم.\nguid\nاتباع سنة النبي -صلى الله عليه وسلم- من أسباب الهداية إلى الطريق المستقيم.\nمصير الأمور ومرجعها إلى الله سبحانه؛ فلا تتوكل إلا عليه.\nالمسرف في الغفلة قد يكون أنفع للمسلمين من غيره إذا اهتدى.\nrefl\nوَكَذَٰلِكَ أَوۡحَيۡنَآ إِلَيۡكَ رُوحٗا مِّنۡ أَمۡرِنَاۚ\nهو القرآن؛ وسماه روحًا لأن فيه حياة من موت الجهل... وكان مالك بن دينار يقول: \"يا أهل القرآن، ماذا زرع القرآن في قلوبكم؟! فإن القرآن ربيع القلوب كما أن الغيث ربيع الأرض\". القرطبي:١٨/٥٠٩.\nفي تسمية القرآن روحًا حثٌ ودلالة بليغة، وضح ذلك.\nمَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ وَلَا ٱلۡإِيمَٰنُ\nذكر سبحانه صفة رسوله قبل أن يوحى إليه فقال: ﴿مَا كُنتَ تَدۡرِي مَا ٱلۡكِتَٰبُ﴾ أي: أي شيء هو؛ لأنه -صلى الله عليه وآله وسلم- كان أميًّا لا يقرأ ولا يكتب، وذلك أدخل في الإعجاز، وأدل على صحة نبوته. الشوكاني:٤/٥٤٥.\nدلت الآية الكريمة على صحة نبوة النبي -صلى الله عليه وسلم-؛ بين ذلك.\nوَلَٰكِن جَعَلۡنَٰهُ نُورٗا نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ٥٢\nشبه الكتاب بالنّور لمناسبة الهُدي به؛ لأن الإيمان والهُدى والعلم تشبَّه بالنور؟ والضلال والجهل والكفر تشبه بالظلمة؛ قال تعالى: ﴿يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ﴾ [البقرة: ٢٥٧]، وإذا كان السائر في الطريق في ظلمة ضل عن الطريق، فإذا استنار له اهتدى إلى الطريق؛ فالنّور وسيلة الاهتداء، ولكن إنَّما يهتدي به من لا يكون له حائل دون الاهتداء، وإلا لم تنفعه وسيلة الاهتداء؛ ولذلك قال تعالى: ﴿نَّهۡدِي بِهِۦ مَن نَّشَآءُ مِنۡ عِبَادِنَاۚ﴾. ابن عاشور:٢٥/١٥٤.\nلماذا شبه الكتاب بالنور؟ ومن المنتفع بنور الكتاب الكريم؟\nوَإِنَّهُۥ فِيٓ أُمِّ ٱلۡكِتَٰبِ لَدَيۡنَا لَعَلِيٌّ حَكِيمٌ ٤\nبَيَّن شرفه في الملأ الأعلى ليشرفه ويعظمه ويطيعه أهل الأرض. ابن كثير:٤/١٢٤.\nلماذا أخبر الله بشرف هذا الكتاب وعلوه عند الملأ الأعلى؟\nأَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ٥\nقال قتادة: \"والله لو كان هذا القرآن رُفع حين رَدَّتهُ أوائل هذه الأمة لهلكوا؛ ولكن الله رَدَّدهُ وكرره عليهم برحمته\". القرطبي:١٩/٧.\nكيف يكون حالنا لو رُفع عنا القرآن حين رده الناس عند أول نزوله؟\nأَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمٗا مُّسۡرِفِينَ ٥\nإن حالكم وإن اقتضى تخليتكم وشأنكم حتى تموتوا على الكفر والضلالة، وتبقوا في العذاب الخالد، لكننا لسعة رحمتنا لا نفعل ذلك، بل نهديكم إلى الحق بإرسال الرسول الأمين، وإنزال الكتاب المبين. الألوسي:٢٥/٩٠.\nكيف دلَّت الآية على سعة رحمة الله تعالى وفضله؟\nوَمَا يَأۡتِيهِم مِّن نَّبِيٍّ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ٧\nيعزي نبيه محمدًا -صلى الله عليه وسلم- ويسليه. القرطبي:١٩/٩.\nما المقصود من ذكر استهزاء أقوام الأنبياء ممن مضى؟"],[490,"§الزخرف\nwords\nبِقَدَرٍبِمِقدَار وَوَزنٍ مَعلُومٍ.\nمُقرِنِينَمُطِيقِينَ.\nوَأَصفَاكُمخَصَّكُم.\nكَظِيمٌمُمتَلِئٌ حُزنًا، وَغَمًّا.\nيُنَشَّأُيُرَبَّى.\nالحِليَةِالزِّينَةِ.\ndeeds\nعدد بعض نعم الله عليك بقولك: \"أنعم ربي علي بكذا وكذا\"، ثم اشكره عليها.\nإذا ركبت السيارة أو الطائرة أو السفينة أو المصعد أو الدواب فقل.\nانظر عبادة يعملها أحد والديك واعمل بها وادع الله لهما، وانظر عملًا خاطئًا يعمله أحد والديك واجتنبه، واسأل الله الهداية لهما.\nguid\nمن تعظيم الله تعالى إفراده بالعبادة.\nعِظَم منزلة الملائكة عند الله.\nمن أعظم ما يصد عن الله تعالى التقليد الخاطئ للآباء واتباع العادات والتقاليد إذا كانت مخالفة للكتاب والسنة.\nrefl\nوَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ\nقال ابن عباس: \"أي: لا كما أنزل على قوم نوح بغير قدر حتى أغرقهم، بل هو بقدر: لا طوفان مغرق ولا قاصر عن الحاجة، حتى يكون معاشًا لكم ولأنعامكم\". القرطبي:١٩/١١.\nما سر قوله عن نزول الماء (بقدر)؟\nوَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَنشَرۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ تُخۡرَجُونَ ١١\nانتقل من الاستدلال والامتنان بخلق الأرض إلى الاستدلال والامتنان بخلق وسائل العيش فيها؛ وهو ماء المطر الذي به تُنبت الأرض ما يصلح لاقتيات الناس. ابن عاشور:٢٥/١٧٠.\nيتدرج القرآن الكريم في الأدلة، بين ذلك من خلال الآية الكريمة.\nوَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَٰمِ مَا تَرۡكَبُونَ ١٢ لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\n﴿وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ﴾ أي: لصائرون إليه بعد مماتنا، وإليه سيرنا الأكبر. وهذا من باب التنبيه بسير الدنيا على سير الآخرة؛ كما نبه بالزاد الدنيوي على الزاد الأخروي في قوله تعالى: ﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰ﴾ [البقرة: ١٩٧]، وباللباس الدنيوي على الأخروي في قوله تعالى: ﴿وَرِيشًاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٌ﴾ [الأعراف: ٢٦]. ابن كثير٤/١٢٦.\nكثيرًا ما تدلنا أمورنا الدنيوية على الأحوال الأخروية، بَيِّن ذلك من خلال الآيات السابقة.\nوَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\nأي: راجعون، وفيه إيذان بأن حق الراكب أن يتأمل فيما يلابسه من السَّير، ويتذكر منه المسافرة العظمى التي هي الانقلاب إلى اللّه تعالى، فيـبـني أموره في مسيره ذلك على تلك الملاحظة، ولا يأتي بما ينافيها، ومن ضرورة ذلك أن يكون ركوبه لأمر مشروع، وفيه إشارة إلى أن الركوب مخطرة فلا ينبغي أن يغفل فيه عن تذكر الآخرة. الألوسي:٢٥/٩٦.\nكيف كان ركوب الدابة وما نحوها والسفر مُذكِّرًا بالآخرة؟\nلِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ ١٣ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ١٤\nوروى مسلم أن النبي -صلى الله عليه وسلم- كان إذا ركب راحلته كَبَّرَ ثلاثًا، ثم قال: ﴿سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ﴾ ثم يقول: «اللهم إني أسألك في سفري هذا البِرَّ والتقوى، ومن العمل ما ترضى. اللهم هَوِّن علينا السفر واطوِ لنا البعيد. اللهم أنت الصاحب في السفر والخليفة في الأهل. اللهم اصحبنا في سفرنا واخلفنا في أهلنا»، وكان إذا رجع إلى أهله قال: «آيبون تائبون إن شاء الله، عابدون، لربنا حامدون». البقاعي:٧/١٣.\nكيف يكون العمل بهذه الآية الكريمة؟\nأَمِ ٱتَّخَذَ مِمَّا يَخۡلُقُ بَنَاتٖ وَجَعَلُواْ ٱلۡمَلَٰٓئِكَةَ ٱلَّذِينَ هُمۡ عِبَٰدُ ٱلرَّحۡمَٰنِ إِنَٰثًاۚ\nتجرؤوا على الملائكة العباد المقربين، ورقوهم عن مرتبة العبادة والذل إلى مرتبة المشاركة لله في شيء من خواصه، ثم نزلوا بهم عن مرتبة الذكورية إلى مرتبة الأنوثية؛ فسبحان من أظهر تناقض من كذب عليه وعاند رسله! السعدي:٧٦٤.\nفي قول المشركين تناقضٌ واضحٌ؛ بَيِّنهُ.\nأَوَ مَن يُنَشَّؤُاْ فِي ٱلۡحِلۡيَةِ وَهُوَ فِي ٱلۡخِصَامِ غَيۡرُ مُبِينٖ ١٨\nالنشوء في الزينة والنعومة من المعايب والمذام، وأنه من صفات ربات الحجال؛ فعلى الرجل أن يجتنب ذلك، ويأنف منه، ويربأ بنفسه عنه، ويعيش كما قال عمر -رضي اللّه تعالى عنه-: \"اخشوشنوا في اللباس، واخشوشنوا في الطعام، وتمعددوا\"، وإن أراد أن يزين نفسه زينها من باطن بلباس التقوى. الألوسي:٢٥/٩٩.\nهل صفات النعومة والمبالغة في الزينة والتجمل تليق بالرجل؟ ولماذا؟"],[491,"§الزخرف\nwords\nبَرَاءٌبَرِيءٌ.\nفَطَرَنِيخَلَقَنِي.\nسُخرِيًّامُسَخَّرًا فِي العَمَلِ.\nوَمَعَارِجَسَلاَلِمَ مِن فِضَّةٍ.\nيَظهَرُونَيَصعَدُونَ.\ndeeds\nضع خطةً للقضاء على أنواع الترف في حياتك الذي يجعلك ترتكب محرمًا أو تترك واجبًا.\nاكتب ثلاثة مظاهر في تحقيق إبراهيم -عليه السلام- للتوحيد.\nدوِّن ما مرَّ بك اليوم من أنواع تسخير الله تعالى الناس بعضهم لبعض.\nguid\nالترف من أسباب التكبر والبعد عن الحق فاحذره.\nاعلم أن القائم بالدعوة معرض للسخرية والاستهزاء، فلا يَضِركَ هذا فهي سنة ماضية.\nمن رحمة الله بعباده تسخير بعضهم لبعض، وجعل الفقير يحتاج إلى الغني، والغني يحتاج إلى الفقير.\nrefl\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ٢٦\nلما ذكر لهم الأدلة، وحذَّرهم بالأخذ، وتحرر أنهم مع التقليد لا ينفكون عنه، ذكَّرَهم بأعظم آبائهم، ومحط فخرهم، وأحقهم بالاتباع؛ للفوز باتِّباع الأب في ترك التقليد أو في تقليده إن كان لا بد لهم من التقليد؛ لكونه أعظم الآباء، ولكونه مع الدليل. البقاعي:٧/٢١.\nلماذا ذكرت قصة إبراهيم بعد ذكر حال المشركين المتمسكين بدين الآباء؟\nوَإِذۡ قَالَ إِبۡرَٰهِيمُ لِأَبِيهِ وَقَوۡمِهِۦٓ إِنَّنِي بَرَآءٞ مِّمَّا تَعۡبُدُونَ ٢٦\nبراءة إبراهيم مما يَعبُد أبُوه أدَلُّ على تجنب عبادة الأصنام بحيث لا يتسامح فيها، ولو كان الذي يعبدها أقربَ النّاس إلى موحّد الله... مثل الأب. ابن عاشور:٢٥/١٩٢.\nلماذا خُص أبو إبراهيم -عليه السلام- بالذكر قبل قومه؟\nوَجَعَلَهَا كَلِمَةَۢ بَاقِيَةٗ فِي عَقِبِهِۦ لَعَلَّهُمۡ يَرۡجِعُونَ ٢٨\n(وجعلها) أي: هذه الخصلة الحميدة التي هي أم الخصال وأساسها؛ وهي إخلاص العبادة لله وحده، والتبري من عبادة ما سواه.... فلم تزل هذه الكلمة موجودة في ذريته -عليه السلام- حتى دخلهم الترف والطغيان. السعدي:٧٦٤.\nما تأثير الترف والطغيان على عقيدة التوحيد؟\nوَلَمَّا جَآءَهُمُ ٱلۡحَقُّ قَالُواْ هَٰذَا سِحۡرٞ وَإِنَّا بِهِۦ كَٰفِرُونَ ٣٠\nوهذا من أعظم المعاندة والمشاقة؛ فإنهم لم يكتفوا بمجرد الإعراض عنه، بل ولا جحده، فلم يرضوا حتى قدحوا به قدحًا شنيعًا، وجعلوه بمنزلة السحر الباطل الذي لا يأتي به إلا أخبث الخلق وأعظمهم افتراء. السعدي:٧٦٥.\nما الذي تفهمه من حال المشركين من قولهم: ﴿هَٰذَا سِحۡرٌ﴾؟\nوَقَالُواْ لَوۡلَا نُزِّلَ هَٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلٖ مِّنَ ٱلۡقَرۡيَتَيۡنِ عَظِيمٍ ٣١ أَهُمۡ يَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَيۡنَهُم مَّعِيشَتَهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ\nفإذا كانت معايش العباد وأرزاقهم الدنيوية بيد الله تعالى؛ هو الذي يقسمها بين عباده -فيبسط الرزق على من يشاء، ويضيقه على من يشاء، بحسب حكمته-؛ فرحمته الدينية -التي أعلاها النبوة والرسالة- أولى وأحرى أن تكون بيد الله تعالى؛ فالله أعلم حيث يجعل رسالته؛ فعلم أن اقتراحهم ساقط لاغ، وأن التدبير للأمور كلها -دينيها ودنيويها- بيد الله وحده. السعدي:٧٦٥.\nلماذا ذكر قسمة الأرزاق بعد اقتراحهم نزول القرآن على رجل من القريتين؟\nوَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضٖ دَرَجَٰتٖ لِّيَتَّخِذَ بَعۡضُهُم بَعۡضٗا سُخۡرِيّٗاۗ وَرَحۡمَتُ رَبِّكَ خَيۡرٞ مِّمَّا يَجۡمَعُونَ ٣٢\nوهو من التسخير في الخدمة: أي رفعنا بعضهم فوق بعض ليخدم بعضهم بعضًا. ابن جزي:٢/٣١٢.\nفي اختلاف منازل الناس ودرجاتهم الدنيوية حكمة عظيمة، فما هي؟\nوَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ٣٣\nقال الحسن: \"المعنى لولا أن يكفر الناس جميعًا -بسبب ميلهم إلى الدنيا وتركهم الآخرة-؛ لأعطيناهم في الدنيا ما وصفناه؛ لهوان الدنيا عند الله -عز وجل-\". القرطبي:١٩/٣٧-٣٨.\nبيّن حقارة الدنيا عند الله المستفاد من الآية."],[492,"§الزخرف\nwords\nوَزُخرُفًاذَهَبًا.\nوَإِن كُلُّ ذَلِكَ لَمَّامَا كُلُّ ذَلِكَ إلَّا.\nيَعشُيُعرِض.\nنُقَيِّضنُهَيِّئ وَنُيَسِّر.\nقَرِينٌمُلاَزِمٌ وَمُصَاحِبٌ.\nبُعدَ المَشرِقَينِمِثلَ تَبَاعُدِ مَا بَينَ المَشرِقِ وَالمَغرِبِ.\ndeeds\nقل: \"سبحان الله وبحمده، سبحان الله العظيم مائة مرة\".\nتعرف على سنة مهجورة وحاول تطبيقها متمسكًا بها.\nتذكر لحظات طويلة مرت عليك لم تذكر الله فيها ثم تذكر أن الشيطان كان قرينك فيها.\nguid\nاحذر أن تعمل عملًا تظن أنك مهتد فيه وأنت على ضلال، وعلاج ذلك العلم بالدليل الصحيح.\nالتمسك بالكتاب والسنة فيهما العصمة والنجاة في الدنيا والآخرة.\nالسخرية من الدين وأهله من صفات الكفار والمنافقين.\nrefl\nلَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ وَمَعَارِجَ عَلَيۡهَا يَظۡهَرُونَ ٣٣ وَلِبُيُوتِهِمۡ أَبۡوَٰبٗا وَسُرُرًا عَلَيۡهَا يَتَّكِـُٔونَ ٣٤ وَزُخۡرُفٗاۚ وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ\nأي: لزخرف لهم دنياهم بأنواع الزخارف، وأعطاهم ما يشتهون، ولكن منعه من ذلك رحمته بعباده؛ خوفًا عليهم من التسارع في الكفر وكثرة المعاصي بسبب حب الدنيا. ففي هذا دليل على أنه يمنع العباد بعض أمور الدنيا منعًا عامًا أو خاصًا لمصالحهم. السعدي:٧٦٥.\nفي الآية دليل على أن من رحمته سبحانه أن يمنع عباده أحيانًا من بعض زخارف الدنيا، وضح ذلك.\nوَمَن يَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَٰنِ نُقَيِّضۡ لَهُۥ شَيۡطَٰنٗا فَهُوَ لَهُۥ قَرِينٞ ٣٦ وَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٧\nلأن من وُسِّع عليه في دنياه اشتغل في الأغلب عن ذكر الله، فنفرت منه الملائكة ولزمته الشياطين، فساقه ذلك إلى كل سوء، ومَن يتق الله فيديم ذكره يؤيده بملَك فهو له مُعِين. البقاعي:٧/٢٧-٢٨.\nاذكر شيئًا من أضرار الغفلة عن ذكر الله تعالى.\nوَإِنَّهُمۡ لَيَصُدُّونَهُمۡ عَنِ ٱلسَّبِيلِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٧\nفإن قيل: فهل لهذا من عذر، من حيث إنه ظن أنه مهتدٍ وليس كذلك؟ قيل: لا عذر لهذا وأمثاله؛ الذين مصدر جهلهم الإعراض عن ذكر الله، مع تمكنهم على الاهتداء، فزهدوا في الهدى مع القدرة عليه، ورغبوا في الباطل، فالذنب ذنبهم، والجرم جرمهم. السعدي:٧٦٦.\nهل للضالين من عذر، من حيث إنهم ظنوا أنهم مهتدون وليسوا كذلك؟\nوَلَن يَنفَعَكُمُ ٱلۡيَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ ٣٩\nهذا كلام يقال للكفار في الآخرة، ومعناه أنهم لا ينفعهم اشتراكهم في العذاب، ولا يجدون راحة التأسي التي يجدها المكروب في الدنيا إذا رأى غيره قد أصابه مثل الذي أصابه. ابن جزي:٢/٣١٤.\nبيّن العذاب النفسي الذي يجده الغافل عن ذكر الله في الآخرة.\nأَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِي ٱلۡعُمۡيَ وَمَن كَانَ فِي ضَلَٰلٖ مُّبِينٖ ٤٠\nفالمعنى: ليس شيء من ذلك إليك، بل هو إلى الله القادر على كل شيء، وأمَّا أنت فليس عليك إلا البلاغ. البقاعي:٧/٣٠.\nما المهمة الأساس للدعاة إلى الله تعالى؟\nوَإِنَّهُۥ لَذِكۡرٞ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ ٤٤\nالضمير في (وإنه) للقرآن أو للإسلام، والذكر هنا بمعنى الشرف، وقوم النبي -صلى الله عليه وسلم- هم قريش وسائر العرب؛ فإنهم نالوا بالإسلام شرف الدنيا والآخرة، ويكفيك أن فتحوا مشارق الأرض ومغاربها. ابن جزي:٢/٣١٤.\nما الشرف الذي ناله العرب بالتمسك بالإسلام؟\nوَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَقَالَ إِنِّي رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ ٤٦\nولما كان المترفون مولعين بأن يزدَرُوا مَن جاءهم... بنوع من الازدراء... ولا يزالون [يوردون] هذا وأمثاله من الضلال حتى يقهرهم ذو الجلال بما أتتهم به رسله؛ إما بإهلاكهم أو غيره، وإن كانوا في غاية القوة، أورد سبحانه قصة موسى -عليه الصلاة والسلام- شاهدة على ذلك بما قال فرعون لموسى -عليه الصلاة والسلام- من نحو ذلك، ومن إهلاكه على قوته، وإنجاء بني إسرائيل على ضعفهم. البقاعي:٧/٣٣.\nما موقف المترفين من الناصحين؟ وما سنة الله سبحانه في خاتمة الفريقين؟"],[493,"§الزخرف\nwords\nيَنكُثُونَيَغدِرُونَ، وَيُصِرُّونَ عَلَى الكُفرِ.\nمَهِينٌضَعِيفٌ لاَ عِزَّ لَهُ.\nمُقتَرِنِينَمَقرُونِينَ مَعَهُ يُصَدِّقُونَهُ.\nآسَفُونَاأَغضَبُونَا.\ndeeds\nتذكر مصيبة أصابتك، ثم تذكر ذنبًا فعلته قبلها واستغفر الله منه؛ فربما أصبت بالمصيبة لكي ترجع إلى ربك.\nتأمل تسلسل المصائب على الأمة من الصغرى إلى الكبرى ثم قل: \"اللهم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك\".\nتصدق؛ فإن الصدقة تطفئ غضب الرب.\nguid\nالمصائب التي تحل بالعباد تكون إنذارًا من الله لهم ليتوبوا ويرجعوا.\nابتعد عن معاصي الله ومخالفة أمر نبيه محمد -عليه الصلاة والسلام- تسلم من غضب الله وعقابه.\nاحذر من الطغيان بالقول والفعل؛ فإن مآل ذلك الذلة في الدنيا والآخرة؛ فهاهم قوم فرعون لمَّا طغوا أنزل الله فيهم عقوبته.\nrefl\nوَمَا نُرِيهِم مِّنۡ ءَايَةٍ إِلَّا هِيَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ يَرۡجِعُونَ ٤٨\nبيَّن سبحانه أن العلة فى أخذه لهم بالعذاب هو رجاء رجوعهم. الشوكاني:٤/٥٥٩.\nتظهر رحمة الله تعالى بخلقه حتى في عذابهم الدنيوي، بين ذلك من خلال الآية الكريمة.\nوَقَالُواْ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ ٤٩\n(يا أيها الساحر) يعنون: موسى -عليه السلام-، وهذا إما من باب التهكم به، وإما أن يكون الخطاب عندهم مدحًا، فتضرعوا إليه بأن خاطبوه بما يخاطبون به من يزعمون أنهم علماؤهم وهم السحرة. السعدي:٧٦٧.\nلا غنى للمجمتع عن العلماء والعباد، بين هذا من خلال الآية.\nوَنَادَىٰ فِرۡعَوۡنُ فِي قَوۡمِهِۦ قَالَ يَٰقَوۡمِ أَلَيۡسَ لِي مُلۡكُ مِصۡرَ وَهَٰذِهِ ٱلۡأَنۡهَٰرُ تَجۡرِي مِن تَحۡتِيٓۚ أَفَلَا تُبۡصِرُونَ ٥١\nوهذا من جهله البليغ؛ حيث افتخر بأمر خارج عن ذاته، ولم يفخر بأوصاف حميدة، ولا أفعال سديدة. السعدي:٧٦٧.\nفي مدح فرعون لنفسه جهلٌ عظيم، بيِّن ذلك.\nفَلَوۡلَآ أُلۡقِيَ عَلَيۡهِ أَسۡوِرَةٞ مِّن ذَهَبٍ أَوۡ جَآءَ مَعَهُ ٱلۡمَلَٰٓئِكَةُ مُقۡتَرِنِينَ ٥٣\nنظر إلى الشكل الظاهر، ولم يفهم السر المعنوي الذي هو أظهر مما نظر إليه لو كان يفهم. ابن كثير:٤/١٣٢.\nلم تكن نظرة فرعون إلى موسى نظرة سليمة، بيِّن ذلك.\nفَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُواْ قَوۡمٗا فَٰسِقِينَ ٥٤\nأي استخف فرعون قومه القبط؛ أي: وجدهم جهالًا. وقيل: حملهم على الخفة والجهل. البغوي:٤/١٠٣.\nمن أسباب انتشار البدع والضلال في المجتمع الجهل، وضح ذلك.\nفَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ ٥٥\nقال عمر بن ذر: \"يا أهل معاصي الله، لا تغتروا بطول حلم الله عنكم، واحذروا أَسَفَهُ؛ فإنه قال: ﴿فَلَمَّآ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ﴾\". القرطبي:١٩/٦٤.\nبيّن خطورة الاغترار والتمادي بالمعاصي في ضوء الآية.\nفَجَعَلۡنَٰهُمۡ سَلَفٗا وَمَثَلٗا لِّلۡأٓخِرِينَ ٥٦\nفيكون حالهم عظةً لناس وإضلالًا لآخرين؛ فمن قضى أن يكون على مثل حالهم عمل مثل أعمالهم، ومن أراد النجاة مما نالهم تجنب أفعالهم. البقاعي:٧/٣٩.\nكيف جعل الله أحوال الأمم السابقة عظة لناس وإضلالاَ لآخرين؟"],[494,"§الزخرف\nwords\nلَعِلمٌ لِلسَّاعَةِإِنَّ نُزُولَ عِيسَى -عليه السلام- لَدَلِيلٌ عَلَى قُربِ وُقُوعِ السَّاعَةِ.\nصِرَاطٌ مُستَقِيمٌطَرِيقٌ قَوِيمٌ إِلَى الجَنَّةِ لاَ عِوَجَ فِيهِ.\nبِالحِكمَةِبِالنُّبُوَّةِ.\nبَغتَةًفَجأَةً.\nالأَخِلاَّءُالأَصدِقَاءُ وَالأَحبَابُ.\nتُحبَرُونَتُنَعَّمُونَ وَتُسَرُّونَ.\nبِصِحَافٍبِأَوَانٍ.\ndeeds\nتواصل أنت وأحد زملائك على الصلاة في الصف الأول وقراءة القرآن.\nزُر أخًا لك في الله لا تستهدف من هذه الزيارة إلا استشعار المحبة في الله.\nقل: \"ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا\".\nguid\nالحذر من الاختلاف في الدين.\nاتبع صراط الله في أمورك كلها ولا تَحِد عنه.\nالصداقات التي تقوم على المصالح والمجاملات تنقلب إلى عداوات يوم القيامة.\nrefl\nوَإِنَّهُۥ لَعِلۡمٞ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ٦١\nومعنى قوله: ﴿لَعِلۡمٌ لِّلسَّاعَةِ﴾ على القول الحق الصحيح الذي يشهد له القرآن العظيم والسنة المتواترة: هو أن نزول عيسى في آخر الزمان حيًّا علم للساعة؛ أي علامة لقرب مجيئها لأنه من أشراطها الدالة على قربها. الشنقيطي:٧/١٢٨.\nما المراد بقوله: ﴿لَعِلۡمٌ لِّلسَّاعَةِ﴾؟\nوَلَا يَصُدَّنَّكُمُ ٱلشَّيۡطَٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ ٦٢\nأي: واضح العداوة في نفسه، مناد بها؛ وذلك بإبلاغه في عداوة أبيكم حتى أنزلكم بإنزاله عن محل الراحة إلى موضع النَّصَب، عداوة ناشئة عن الحسد؛ فهي لا تنفك أبدًا. البقاعي:٧/٤٣.\nما منشأ عداوة الشيطان لنا؟ ومتى تنتهي؟\nإِنَّ ٱللَّهَ هُوَ رَبِّي وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطٞ مُّسۡتَقِيمٞ ٦٤\nوتقديم نفسه على قومه في قوله: ﴿رَبِّي وَرَبُّكُمۡ﴾ لقصد سدّ ذرائع الغلوّ في تقديس عيسى، وذلك من معجزاته؛ لأن الله علم أنه ستغلو فيه فِرق من أتباعه فيزعمون بنوَّتَه من الله على الحقيقة. ابن عاشور:٢٥/٢٤٨.\nلماذا قدم عيسى -عليه السلام- نفسه على قومه في قوله: ﴿رَبِّي وَرَبُّكُمۡ﴾؟\nٱلۡأَخِلَّآءُ يَوۡمَئِذِۢ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِينَ ٦٧\nأي: كل صداقة وصحابة لغير الله فإنها تنقلب يوم القيامة عداوة، إلا ما كان لله -عز وجل-؛ فإنه دائم بدوامه. ابن كثير:٤/١٣٥.\nما سبب دوام الصداقة يوم القيامة؟\nيَٰعِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ ٱلۡيَوۡمَ وَلَآ أَنتُمۡ تَحۡزَنُونَ ٦٨\nأي: لا خوف يلحقكم فيما تستقبلونه من الأمور، ولا حزن يصيبكم فيما مضى منها، وإذا انتفى المكروه من كل وجه ثبت المحبوب المطلوب. السعدي:٧٦٩.\nإذا ثبت انتفاء الخوف والحزن عن أهل الجنة؛ فما الذي يثبت لهم؟\nيُطَافُ عَلَيۡهِم بِصِحَافٖ مِّن ذَهَبٖ وَأَكۡوَابٖۖ وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ وَأَنتُمۡ فِيهَا خَٰلِدُونَ ٧١ وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ٧٢ لَكُمۡ فِيهَا فَٰكِهَةٞ كَثِيرَةٞ\nلما ذكر الطعام والشراب ذكر بعده الفاكهة لتتم النعمة والغبطة. ابن كثير:٤/١٣٧.\nلماذا ذكر الفاكهة بعد ذكر الطعام والشراب؟\nوَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِيٓ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ٧٢\nيقال لهم يوم القيامة هذه المقالة؛ أي: صارت إليكم كما يصير الميراث إلى الوارث بما كنتم تعملونه فى الدنيا من الأعمال الصالحة. الشوكاني:٤/٥٦٤.\nما أهمية العمل الصالح من خلال الآية الكريمة؟"],[495,"§الزخرف\nwords\nلاَ يُفَتَّرُ عَنهُملاَ يُخَفَّفُ عَنهُم.\nمُبلِسُونَآيِسُونَ مِن رَحمَةِ اللهِ.\nأَم أَبرَمُوا أَمرًاأَحكَمُوا أَمرًا فِي كَيدِ نَبِيِّنَا مُحَمَّدٍ صلّى الله عليه وسلّم.\nيَخُوضُوايَتَكَلَّمُوا بِبَاطِلِهِم.\nفَأَنَّى يُؤفَكُونَكَيفَ يَنصَرِفُونَ عَن عِبَادَةِ اللهِ؟!\nوَقِيلِهِوَقَولِ مُحَمَّدٍ فِي شَكوَاهُ.\nفَاصفَحأَعرِض عَن أَذَاهُم.\ndeeds\nسبح الله تعالى اقتداء بالآية الكريمة.\nادعُ الله أن تنالك شفاعة نبيك محمد -صلى الله عليه وسلم-.\nاصفح اليوم عمن ظلمك.\nguid\nإحاطة الله تعالى وسعة علمه تدعو العبد إلى مراقبته وتقواه.\nتنزيه الله تعالى عما افتراه عليه الكفار من نسبة الولد إليه.\nأمر الله نبيه بالصفح عن الكافرين، فما أحرانا بالصفح عمن آذانا.\nrefl\nلَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ٧٥\nوالمبلس في هذا الموضع هو: الآيس من النجاة، الذي قد قنط فاستسلم للعذاب والبلاء. الطبري:٢١/٦٤٣.\nما المراد بإبلاس الكفار في النار؟\nلَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُبۡلِسُونَ ٧٥\nأي: حزينون من شدة اليأس. قال الراغب: \"الإبلاس: الحزن المعترض من شدة اليأس، ومنه اشتُقَّ إبليس فيما قيل. ولما كان المُبلِس كثيرًا ما يلزم السكوت وينسى ما يعنيه؛ قيل: أبلس فلان: إذا سكت وانقطعت حجته\" انتهى. وقد فُسِّر الإبلاس هنا بالسكوت وانقطاع الحجة. الألوسي:٢٥/١٤١.\nما معنى (مبلسون)؟\nقَالَ إِنَّكُم مَّٰكِثُونَ ٧٧ لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ٧٨\nفلما سألوا أن يموتوا أجابهم مالك: ﴿قَالَ إِنَّكُم مَّٰكِثُونَ﴾، ثم ذكر سبب شقوتهم، وهو مخالفتهم للحق ومعاندتهم له، فقال: ﴿لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ﴾. ابن كثير:٤/١٣٧.\nما فائدة قوله: ﴿لَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ﴾ بعد قوله: ﴿قَالَ إِنَّكُم مَّٰكِثُونَ﴾؟\nلَقَدۡ جِئۡنَٰكُم بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَٰرِهُونَ ٧٨\nلقد جئناكم في الدنيا بالحق؛ وهو التوحيد وسائر ما يجب الإيمان به؛ وذلك بإرسال الرسل وإنزال الكتب، ولكن أكثركم للحق -أيِّ حقٍ كان- كارهون؛ لا يقبلونه وينفرون منه. الألوسي:٢٥/١٤٢.\nمالمراد بالحق الوارد في الآية؟\nقُلۡ إِن كَانَ لِلرَّحۡمَٰنِ وَلَدٞ فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ ٨١\n﴿فَأَنَا۠ أَوَّلُ ٱلۡعَٰبِدِينَ﴾ لذلك الولد؛ لأنه جزء من والده، وأنا أولى الخلق انقيادًا للأمور المحبوبة لله؛ ولكني أول المنكرين لذلك وأشدهم له نفيًا؛ فعلم بذلك بطلانه. فهذا احتجاج عظيم عند من عرف أحوال الرسل. السعدي:٧٧٠.\nيستفاد من هذه الآية أن الرسل أسبق الناس للكمالات وأبعدهم عن الشرور والنقائص؛ بين وجه هذه الفائدة من الآية.\nسُبۡحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا يَصِفُونَ ٨٢\nوقصد بذكر السماء والأرض الإحاطة بعوالم التدبير والخلق؛ لأن المشركين جعلوا لله شركاء في الأرض؛ وهم أصنامهم المنصوبة، وجعلوا له شركاء في السماء؛ وهم الملائكة، إذ جعلوهم بنات لله تعالى. ابن عاشور:٢٥/٢٦٧.\nلماذا خصت الآية السماوات والأرض بربوبية الله تعالى لهما؟\nفَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَٰمٞۚ فَسَوۡفَ يَعۡلَمُونَ ٨٩\nفليس ذلك أمرًا بالسلام عليهم والتحية، وإنَّما هو أمر بالمتاركة؛ وحاصله إذا أبيتم القبول فأمري التَسَلُّم مِنكُم. الألوسي:٢٥/١٥١.\nأُمرنا بالرفق والحكمة عند عناد المدعوين ورفضهم؛ بين ذلك من خلال الآية."],[496,"§الدخان\nwords\nلَيلَةٍ مُبَارَكَةٍهِيَ: لَيلَةُ القَدرِ مِن شَهرِ رَمَضَانَ.\nيُفرَقُيُقضَى وَيُفصَلُ مِنَ اللَّوحِ المَحفُوظِ إِلَى الكَتَبَةِ مِنَ المَلاَئِكَةِ.\nأَمرٍ حَكِيمٍأَمرٍ مُحكَمٍ؛ مِنَ الآجَالِ، وَالأَرزَاقِ، فِي تِلكَ السَّنَةِ.\nفَارتَقِبانتَظِر بِهَؤُلاَءِ المُشرِكِينَ.\nالبَطشَةَ الكُبرَىالعَذَابَ الأَكبَرَ يَومَ القِيَامَةِ.\nأَدُّوا إِلَيَّسَلِّمُوا لِي عِبَادَ اللهِ مِن بَنِي إِسرَائِيلَ.\ndeeds\nإذا استيقظت من الصباح فقل: \"الحمد لله الذي أحياني بعد ما أماتني وإليه النشور\".\nادع الله تعالى أن يرفع البلاء عن المبتلين.\nصلِّ على النبي -صلى الله عليه وسلم- تعظيمًا له.\nguid\nمن فضائل ليلة القدر: نزول القرآن، وتقسيم الأرزاق؛ فاحرص على اغتنامها وإحيائها بالقيام والذكر والدعاء وتلاوة القرآن.\nإذا جاءك التذكير بربك فتذكر ولا تتكبر حتى لا يطمس الله على بصيرتك.\nالله -عز وجل- يمهل ولا يهمل.\nrefl\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةٖ مُّبَٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِينَ ٣\n﴿فِي لَيۡلَةٍ مُّبَٰرَكَةٍۚ﴾ أي: كثيرة الخير والبركة؛ وهي ليلة القدر التي هي خير من ألف شهر؛ فأنزل أفضل الكلام بأفضل الليالي والأيام على أفضل الأنام بلغة العرب. السعدي:٧٧٣.\nما المراد بالليلة المباركة؟ ولماذا وصفت بالمباركة؟\nفِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَكِيمٍ ٤\nمعنى (يفرق): يفصل ويخلص، والأمر الحكيم: أرزاق العباد وآجالهم، وجميع أمورهم في ذلك العام؛ نُسِخ من اللوح المحفوظ في ليلة القدر ليتمثّل الملائكة ذلك بطول السنة القابلة. ابن جزي:٢/٣٢١.\nما الأمر الحكيم الذي يفرق في ليلة القدر؟\nبَلۡ هُمۡ فِي شَكّٖ يَلۡعَبُونَ ٩\nإِنَّ إِقرارهم غَير صادرٍ عن علمٍ ويقينٍ ثابتٍ، بل هو كَالعَدَمِ؛ لأنَّهُم خَلَطُوهُ بِالشَّكِّ واللَّعب فَارتفَعت عنه خاصِّيَّةُ اليقينِ والإقرارِ الَّتي هي الجَري علَى مُوجَبِ العِلمِ؛ فإن العلم إذا لم يَجُرّ صاحبه على العمل به وتجديد ملاحظته تطرق إليه الذهول ثم النسيان، فضعف حتى صار شكّا. ابن عاشور:٢٥/٢٨٤-٢٨٥.\nبيّن خطورة عدم العمل بالعلم من الآية الكريمة.\nفَٱرۡتَقِبۡ يَوۡمَ تَأۡتِي ٱلسَّمَآءُ بِدُخَانٖ مُّبِينٖ ١٠\nعن أبي هريرة -رضي الله عنه- أن النبي -صلى الله عليه وسلم- قال: «بادروا بالأعمال ستًّا: الدَجَّال، والدخان، ودابة الأرض، وطلوع الشمس من مغربها، وأمر العامة، وَخُوَيصَّةَ أحدكم». البقاعي:٧/٦٨.\nما مساوئ التسويف وتأخير العمل الصالح عن وقته؟\nرَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ ١٢\nوعليه فجملة ﴿إِنَّا مُؤۡمِنُونَ﴾ تعليل لطلب دفع العذاب عنهم؛ أي إنا متلبسون بما يدفع عنا عذاب الكافرين، وفي تلقينهم بذلك تنويه بشرف الإيمان. ابن عاشور:٢٥/٢٩٠.\nكيف أظهرت الآية الكريمة شرف الإيمان؟\n۞وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَآءَهُمۡ رَسُولٞ كَرِيمٌ ١٧\nعن قتادة، في قوله: ﴿رَسُولٌ كَرِيمٌ﴾ قال: \"موسى -عليه السلام-\"، ووصفه جل ثناؤه بالكرم؛ لأنه كان كريمًا عليه، رفيعًا عنده مكانه. وقد يجوز أن يكون وصفه بذلك؛ لأنه كان في قومه شريفًا وسيطًا. الطبري:٢٢/٢٤.\nما وجه وصف نبي الله موسى -عليه الصلاة والسلام- بالكريم؟\nإِنِّي لَكُمۡ رَسُولٌ أَمِينٞ ١٨\nأي: رسول من رب العالمين، أمين على ما أرسلني به، ولا أكتمكم منه شيئًا، ولا أزيد فيه ولا أنقص، وهذا يوجب تمام الانقياد له. السعدي:٧٧٣.\nفي الآية ذم للبدعة والابتداع بينه."],[497,"§الدخان\nwords\nوَأَن لاَ تَعلُواأَلاَّ تَتَكَبَّرُوا.\nبِسُلطَانٍبِبُرهَانٍ وَحُجَّةٍ.\nعُذتُاستَجَرتُ.\nأَن تَرجُمُونِأَن تَقتُلُونِي رَجمًا بِالحِجَارَةِ.\nرَهوًاسَاكِنًا غَيرَ مُضطَرِبٍ.\nمُنظَرِينَمُؤَخَّرِينَ عَنِ العُقُوبَةِ.\nاختَرنَاهُماصطَفَينَاهُم.\nبِمُنشَرِينَبِمَبعُوثِينَ.\ndeeds\nتَعَوَّذ بالله ممن تخافه من عدوٍّ، أو أذى، أو نحو ذلك.\nتذكر كافرًا بالَغَ في إجرامه وأذيته للمؤمنين وادع الله عليه.\nصل ركعتين في مكان لم تصل فيه من قبل حتى يشهد لك.\nguid\nالمؤمن تبكي عليه السماء والأرض لعمله الصالح بعد موته؛ فاعمل صالحًا لتكون كذلك.\nقدرة الله على إهلاك الظالمين.\nالحذر من أسباب هلاك الأمم.\nrefl\nوَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ ٢١ فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوۡمٞ مُّجۡرِمُونَ ٢٢\n﴿وَإِن لَّمۡ تُؤۡمِنُواْ لِي فَٱعۡتَزِلُونِ﴾ أي: فلا تتعرضوا لي، ودعوا الأمر بيني وبينكم مسالمة إلى أن يقضي الله بيننا، فلما طال مقامه بين أظهرهم، وأقام حجج الله تعالى عليهم، كل ذلك وما زادهم ذلك إلا كفرًا وعنادًا، دعا ربه عليهم دعوة نفذت فيهم. ابن كثير:٤/١٤٣.\nما الذي جعل موسى يتحول من حال دعوتهم إلى حال الدعاء عليهم؟\nفَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ\nأي: لم تكن لهم أعمال صالحة تصعد في أبواب السماء فتبكي على فقدهم، ولا لهم في الأرض بقاع عبدوا الله فيها ففقدتهم؛ فلهذا استحقوا أن لا يُنظَروا ولا يؤخروا لكفرهم وإجرامهم وعتوهم وعنادهم. ابن كثير:٤/١٤٤.\nما السبب الذي يجعل السماء والأرض تبكي على العباد؟\nفَمَا بَكَتۡ عَلَيۡهِمُ ٱلسَّمَآءُ وَٱلۡأَرۡضُ وَمَا كَانُواْ مُنظَرِينَ ٢٩\nهذا بيان لعدم الاكتراث بهلاكهم؛ قال المفسرون: أي إنهم لم يكونوا يعملون على الأرض عملًا صالحًا تبكي عليهم به، ولم يصعد لهم إلى السماء عمل طيب يُبكي عليهم به؛ والمعنى أنه لم يُصَب بفقدهم وهلاكهم أحد من أهل السماء ولا من أهل الأرض. الشوكاني:٤/٥٧٥.\nبيّن مهانة المشركين من خلال الآية الكريمة.\nوَلَقَدِ ٱخۡتَرۡنَٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَٰلَمِينَ ٣٢ وَءَاتَيۡنَٰهُم مِّنَ ٱلۡأٓيَٰتِ مَا فِيهِ بَلَٰٓؤٞاْ مُّبِينٌ ٣٣\nولما كانت قريش تفتخر بظواهر الأمور من الزينة والغرور، ويعدونه تعظيمًا من الله، ويعدون ضعف الحال في الدنيا شقاء وبعدًا من الله، ردَّ عليهم قولهم بما آتى بني إسرائيل، على ما كانوا فيه من الضعف وسوء الحال، بعد إهلاك آل فرعون بعذاب الاستئصال. البقاعي:٧/٧٦.\nهل الغِنى في الدنيا دليل على محبة الله تعالى ورضاه عن العبد الغني؟ والفقر دليل على بغض الله وسخطه على الفقير؟\nأَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ٣٧\nفبعد أن ضرب لهم المثل بمهلك قوم فرعون زادهم مثلًا آخر هو أقرب إلى اعتبارهم به؛ وهو مَهْلِكُ قوم أقرب إلى بلادهم من قوم فرعون؛ وأولئك قوم تبّع، فإن العرب يتسامعون بعظمة مُلك تُبَّع وقومه أهل اليمن، وكثير من العرب شاهدوا آثار قوتهم وعظمتهم في مراحل أسفارهم، وتحادثوا بما أصابهم من الهلك بسيل العرم. ابن عاشور:٢٥/ ٣٠٨.\nما فائدة ضرب المثل بقوم تُبَّع؟\nأَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّعٖ وَٱلَّذِينَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَٰهُمۡۚ إِنَّهُمۡ كَانُواْ مُجۡرِمِينَ ٣٧\nومعنى الآية: أقريش أشدّ وأقوى، أم قوم تبع والذين من قبلهم من الكفار؟! وقد أهكلنا قوم تبع وغيرهم لمَّا كفروا؛ فكذلك نهلك هؤلاء. فمقصود الكلام تهديد. ابن جزي:٢/٣٢٤.\nاشرح التهديد الوارد في هذه الآية.\nوَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ ٣٨ مَا خَلَقۡنَٰهُمَآ إِلَّا بِٱلۡحَقِّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٣٩\nفهم لأجل ذلك يجترئون على المعاصي ويفسدون في الأرض؛ لا يرجون ثوابًا ولا يخافون عقابًا. البقاعي:٧/٧٩.\nما الذي يُجرِّئ العبد على المعاصي والفساد؟ وما الذي يحمل الإنسان على الاستقامة والصلاح؟"],[498,"§الدخان\nwords\nالأَثِيمِصَاحِبِ الآثَامِ الكَبِيرَةِ.\nكَالمُهلِكَالمَعدَنِ المُذَابِ.\nفَاعتِلُوهُجُرُّوهُ وَسُوقُوهُ بِعُنفٍ.\nسُندُسٍهُوَ: الرَّقِيقُ مِنَ الدِّيبَاجِ.\nوَإِستَبرَقٍهُوَ: الغَلِيظُ مِنَ الدِّيبَاجِ.\nالمَوتَةَ الأُولَىالَّتِي ذَاقُوهَا فِي الدُّنيَا.\nفَارتَقِبانتَظِر نَصرَكَ، وَهَلاَكَهُم.\ndeeds\nادعُ الله أن يرحمك يوم الفصل.\nقل: \"اللهم إني أعوذ بك من النار وما قرب إليها من قول وعمل\".\nسَلِ الله تعالى أن تكون من أهل المقام الأمين في الجنات والعيون.\nguid\nشدة ما يلاقيه الكفار يوم القيامة من العذاب والمهانة والتبكيت.\nكل ما يعطاه المؤمن من نعيم هو محض منة الله تعالى عليه.\nمن مقاصد نزول القرآن: التذكر والاتعاظ.\nrefl\nإِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ ٤٢\nأي أن الله (عزيز) لا يُكرهه أحد على العدول عن مراده؛ فهو يرحم من يَرحمه بمحض مشيئته، وهو (رحيم): أي واسع الرحمة لمن يشاء من عباده على وفق ما جرى به علمه وحكمته ووعدُه. وفي الحديث: «ارحموا من في الأرض يرحمكم من في السماء». ابن عاشور:٢٥/٣١.\nبيّن مناسبة ختام الآية الكريمة بالاسمين ﴿ٱلۡعَزِيزُ ٱلرَّحِيمُ﴾.\nذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ ٤٩\nيقال هذا للكافر على وجه التوبيخ والتهكم به؛ أي كنت العزيز الكريم عند نفسك. وروي أن أبا جهل قال: ما بين جبليها أعز مني ولا أكرم؛ فنزلت الآية. ابن جزي:٢/٣٢٤.\nكيف يوصف الكافر يوم القيامة ب\"العزيز والكريم\"، وهو في حال عذاب؟\nإِنَّ ٱلۡمُتَّقِينَ فِي مَقَامٍ أَمِينٖ ٥١\nوالأمن أكبر شروط حسن المكان؛ لأن الساكن أولُ ما يتطلب الأمن -وهو السلامة من المكاره والمخاوف- فإذا كان آمنًا في منزله كان مطمئن البال شاعرًا بالنعيم الذي يناله. ابن عاشور:٢٥/٣١٧.\nبيّن عظيم الامتنان بنعمة الأمن في الآية الكريمة.\nيَلۡبَسُونَ مِن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَقَٰبِلِينَ ٥٣\nلا يجلس أحدٌ منهم وظهره إلى غيره. ابن كثير:٤/١٤٨.\nليس في الجنة أدنى نوعٍ من أنواع الإهانات، بيِّن ذلك من خلال الآية.\nيَدۡعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ ٥٥\nيقول: ليست تلك الفاكهة هنالك كفاكهة الدنيا التي نأكلها؛ وهم يخافون مكروه عاقبتها وغِب أذاها، مع نفادها من عندهم وعدمها في بعض الأزمنة والأوقات. الطبري:٢٢/٥٣.\nما المناسبة في ذكر الفاكهة مقرونة بالأمن في الآية؟\nفَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ٥٨\nأي: إنَّما يسرنا هذا القرآن الذي أنزلناه سهلًا واضحًا بينًا جليًا بلسانك الذي هو أفصح اللغات وأجلاها وأحلاها وأعلاها. ابن كثير:٤/١٤٩.\nتكلم عن فضل اللغة العربية على سائر اللغات من خلال الآية.\nفَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ ٥٩\nأي ارتقب نصرنا لك وإهلاكهم؛ فإنهم مرتقبون ضدّ ذلك؛ ففيه وعد له ووعيد لهم. ابن جزي:٢/٣٢٥.\nاشرح كيف جمعت الآية بين الوعد والوعيد."],[499,"§الجاثية\nwords\nيَبُثُّيَنشُرُ، وَيُفَرِّقُ.\nوَيلٌهَلاَكٌ، وَدَمَارٌ.\nأَفَّاكٍكَذَّابٍ.\nأَثِيمٍكَثِيرِ الإِثمِ.\nهُزُوًاسُخرِيَةً.\ndeeds\nتأمل طريقة مشي الإنسان والبعير والحية، واكتب الفرق بينها، وعلى ماذا يدل هذا الاختلاف.\nاكتب ثلاث فوائد ومنافع من تعاقب الليل والنهار.\nتذكر معصية فعلتها، ثم تذكر آية تنهى عنها، ثم استغفر الله سبحانه.\nguid\nإذا جاءك العلم من الله ومن رسوله -صلى الله عليه وسلم- فحسبك به ولا تتبع أهواء الرجال.\nإياك أن تستهزئ بشيء له صلة بالدِّين؛ فإن إثم ذلك عظيم.\nالتفكر في مخلوقات الله من أنفع ما يعين العبد على شكر الله وتوحيده.\nrefl\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ٢\nإِيثار وصفَيِ ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ بِالذكرِ دون غَيرِهما من الأسماء الحسنى لإِشعارِ وصف العزِيزِ بِأَن ما نزل منه مناسب لعزته؛ فَهو كتاب عزِيز كَما وصفَه تعالَى بِقَوله: ﴿إِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ﴾ [فصلت: ٤١]؛ أي هو غالب لمعانديه؛ وذلك لأنه أعجزهم عن معارضته، ولإشعار وصف (الحكيم) بأن ما نزل من عنده مناسب لحكمته. ابن عاشور:٢٥/٣٢٥.\nلمَ ذُكِر اسمًا ﴿ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ دون غيرهما من الأسماء الحسنى؟\nلَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ٣ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ٤ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ٥\nقال أولًا: ﴿لَأٓيَٰتٍ لِّلۡمُؤۡمِنِينَ﴾، ثم (يوقنون)، ثم (يعقلون)؛ وهو ترقٍّ من حال شريف إلى ما هو أشرف منه وأعلى. ابن كثير:٤/١٥٠.\nبيّن سبب تقديم الإيمان، ثم اليقين، ثم العقل في وصف المؤمنين؟\nإِنَّ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَأٓيَٰتٖ لِّلۡمُؤۡمِنِينَ ٣ وَفِي خَلۡقِكُمۡ وَمَا يَبُثُّ مِن دَآبَّةٍ ءَايَٰتٞ لِّقَوۡمٖ يُوقِنُونَ ٤ وَٱخۡتِلَٰفِ ٱلَّيۡلِ وَٱلنَّهَارِ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ ٱلرِّيَٰحِ ءَايَٰتٞ لِّقَوۡمٖ يَعۡقِلُونَ ٥\nستة براهين من براهين التوحيد الدالة على عظمته وجلاله، وكمال قدرته، وأنه المستحق للعبادة وحده تعالى؛ الأول منها: خلقه السماوات والأرض. الثاني: خلقه الناس. الثالث: خلقه الدواب. الرابع: اختلاف الليل والنهار. الخامس: إنزال الماء من السماء وإحياء الأرض به. السادس: تصريف الرياح. الشنقيطي: ٧/١٧٩.\nذكر الله في هذه الآيات ستة براهين دالة على عظمته وجلاله؛ فما هي؟\nوَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن رِّزۡقٖ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا\nوما أنزل الله -تبارك وتعالى- من السحاب من المطر في وقت الحاجة إليه. وسماه رزقًا؛ لأن به يحصل الرزق. ابن كثير:٤/١٥٠.\nلماذا سمى الله المطر رزقًا؟\nوَيۡلٞ لِّكُلِّ أَفَّاكٍ أَثِيمٖ ٧ يَسۡمَعُ ءَايَٰتِ ٱللَّهِ تُتۡلَىٰ عَلَيۡهِ ثُمَّ يُصِرُّ مُسۡتَكۡبِرٗا كَأَن لَّمۡ يَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٖ ٨\nوقد عُلِم بهذا الوصف أنَّ كُلَّ مَن لم ترُدَّه آياتُ الله تعالى كان مبالِغًا في الإثم والإفك، فكان له الويل. البقاعي:٧/٩٣.\nما مصير من لا يستجيب لهدايات القرآن؟\nمِّن وَرَآئِهِمۡ جَهَنَّمُۖ وَلَا يُغۡنِي عَنۡهُم مَّا كَسَبُواْ شَيۡـٔٗا وَلَا مَا ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَۖ\nوعبر بالوراء عن القدام كقوله ﴿مِّن وَرَآئِهِمۡ جَهَنَّمُۖ﴾... باعتبار إعراضهم عنها؛ كأنها خلفهم. الشوكاني:٥/٥.\nلماذا عبرت الآية الكريمة بالوراء عن القدام؟\nإِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ١٣\nوأوثر التفكر بالذكر في آخر صفات المستدلين بالآيات؛ لأن الفكر هو منبع الإيمان والإيقان والعلم المتقدمة في قوله: ﴿لَأٓيَٰتٍ لِّلۡمُؤۡمِنِينَ﴾، ﴿ءَايَٰتٌ لِّقَوۡمٍ يُوقِنُونَ﴾، ﴿ءَايَٰتٌ لِّقَوۡمٍ يَعۡقِلُونَ﴾. ابن عاشور:٢٥/٣٣٨.\nبيّن فائدة التفكر."],[500,"§الجاثية\nwords\nلاَ يَرجُونَ أَيَّامَ اللهِلاَ يَتَوَقَّعُونَ وَقَائِعَهُ وَعَذَابَهُ بِأَعدَائِهِ.\nوَالحُكمَتَحكِيمَهُمَا.\nلَن يُغنُوا عَنكَلَن يَدفَعُوا عَنكَ.\nبَصَائِرُيُبصِرُ بِهِ النَّاسُ الحَقَّ.\ndeeds\nادع الله -سبحانه وتعالى- أن يجعل العلم سببًا لهدايتك وصلاحك، ولا يجعله سببًا لضلالك وانحرافك.\nطبق الواجبات والسنن، ولو خالفت هواك، مستحضرًا نية اتباع الشريعة.\nاكتب مقالًا أو رسالة تؤكد فيه على أهمية التمسك بشريعة الإسلام منهجًا كاملًا للحياة.\nguid\nتفقد قلبك فإن كان فيه حسد لأحد فادعُ له بالخير واستغفر له.\nأي قول يخالف الكتاب والسنة فهو من الهوى الذي نهى الله عن اتباعه.\nربط الله بين الهوى وعدم العلم؛ فمن كان جاهلًا كان أقرب إلى اتباع الهوى.\nrefl\nمَنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ١٥\nمن عمل من عباد الله بطاعته فانتهى إلى أمره، وانزجر لنهيه؛ فلنفسه عمل ذلك الصالح من العمل، وطلب خلاصها من عذاب الله، أطاع ربه -لا لغير ذلك-؛ لأنه لا ينفع ذلك غيره، والله عن عمل كل عامل غني. ﴿وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ﴾: يقول: ومن أساء عمله في الدنيا؛ بمعصيته فيها ربه، وخلافه فيها أمره ونهيه؛ فعلى نفسه جنى لأنه أوبقها بذلك، وأكسبها به سخطه، ولم يضر أحدًا سوى نفسه. الطبري:٢٢/٦٨.\nلماذا قيد الله تعالى العمل الصالح والسيِّئ بصاحبه؟\nوَلَقَدۡ ءَاتَيۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ١٦ وَءَاتَيۡنَٰهُم بَيِّنَٰتٖ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ١٧\nوهذا فيه تحذير لهذه الأمة أن تسلك مسلكهم، وأن تقصد منهجهم. ابن كثير:٤/١٥٢.\nهاتان الآيتان في بني إسرائيل؛ فما الذي نفيده نحن أمة الإسلام من هاتين الآيتين؟\nوَفَضَّلۡنَٰهُمۡ عَلَى ٱلۡعَٰلَمِينَ ١٦\nكل ما جاء في القرآن من تفضيل بني إسرائيل إنَّما يراد به ذكر أحوال سابقة؛ لأنهم في وقت نزول القرآن كفروا به وكذبوا؛ كما قال تعالى: ﴿فَلَمَّا جَآءَهُم مَّا عَرَفُواْ كَفَرُواْ بِهِۦ﴾ [البقرة: ٨٩]. ومعلوم أن الله لم يذكر لهم في القرآن فضلًا إلا ما يراد به أنه كان في زمنهم السابق، لا في وقت نزول القرآن. الشنقيطي:٧/ ١٩٨-١٩٩.\nوضح معنى تفضيل بني إسرائيل على العالمين.\nفَمَا ٱخۡتَلَفُوٓاْ إِلَّا مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡعِلۡمُ بَغۡيَۢا بَيۡنَهُمۡۚ\nأي حسدًا على النبي -صلى الله عليه وسلم-؛ قيل: معنى (بغيًا) أي: بغى بعضهم على بعض؛ بطلب الفضل والرياسة، وقتلوا الأنبياء؛ فكذا مشركوا عصرك يا محمد، قد جاءتهم البينات ولكن أعرضوا عنها للمنافسة في الرياسة. القرطبي:١٩/١٥٣.\nما البغي الذي وقع منهم؟\nثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٖ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا\nولما كان معنى هذا أنه -سبحانه وتعالى- جعل بني إسرائيل على شريعة وهددهم على الخلاف فيها، فكان تهديدهم تهديدًا لنا؛ قال مصرِّحًا بما اقتضاه سَوق الكلام وغيره مِن تهديدنا، منبهًا على علو شريعتنا: (ثم جعلناك على شريعة من الأمر...) الآية. البقاعي:٧/١٠٠.\nما مناسبة الآية: ﴿ثُمَّ جَعَلۡنَٰكَ عَلَىٰ شَرِيعَةٍ مِّنَ ٱلۡأَمۡرِ﴾ لمَّا قبلها من الآيات؟\nهَٰذَا بَصَٰٓئِرُ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٞ لِّقَوۡمٖ يُوقِنُونَ ٢٠\nوخص -جل ثناؤه- الموقنين بأنه لهم بصائر وهدى ورحمة؛ لأنهم الذين انتفعوا به دون من كذب به من أهل الكفر، فكان عليه عمىً وله حزنًا. الطبري:٢٢/٧٢.\nلماذا خص الله الموقنين بأن القرآن لهم بصائر وهدى ورحمة؟\nأَمۡ حَسِبَ ٱلَّذِينَ ٱجۡتَرَحُواْ ٱلسَّيِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَوَآءٗ مَّحۡيَاهُمۡ وَمَمَاتُهُمۡۚ سَآءَ مَا يَحۡكُمُونَ ٢١\nقال إبراهيم بن الأشعث: كثيرا ما رأيت الفضيل بن عياض يردد من أول الليل إلى آخره هذه الآية ونظيرها، ثم يقول: \"ليت شعري! من أي الفريقين أنت؟\". وكانت هذه الآية تسمى مبكاة العابدين. القرطبي:١٩/١٥٧.\nكيف كان حال السلف مع هذه الآية؟"],[501,"§الجاثية\nwords\nوَخَتَمَطَبَعَ.\nغِشَاوَةًغِطَاءً.\nلاَ رَيبَ فِيهِلاَ شَكَّ فِيهِ.\nإِن نَظُنُّ إِلاَّ ظَنًّامَا نَتَوَقَّعُ وُقُوعَهَا إِلاَّ تَوَهُّمًا.\ndeeds\nحاول تعداد أخطائك ومعاصيك التي فعلتها أو نطقت بها الأسبوع الماضي فقط.\nقل: \"اللهم اجعل في قلبي نورًا، وفي سمعي نورًا، وفي بصري نورًا\".\nقل: \"اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولني فيمن توليت\".\nguid\nاعلم أن أعظم الخذلان أن يضلك الله تعالى وأنت على علم.\nهدايتك وسعادتك ونجاحك بيد الله وحده فاطلبها منه.\nحاسب نفسك قبل أن تحاسب.\nrefl\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\n(اتخذ إلهه هواه) أي: أطاعه حتى صار له كالإله. ابن جزي:٢/٣٢٨.\nكيف يكون الهوى معبودًا من دون الله؟\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\nوفيها مِن ذَمِّ اتباع هوى النفس ما فيها. وعن ابن عباس: \"ما ذَكَرَ الله تعالى هوىً إلا ذمه\". وقال وهب: \"إذا شككتَ في خير أمرين؛ فانظر أبعدهما مِن هواك فأته\". وقال سهل التستري: \"هواك داؤك؛ فإن خالفته فدواؤك\". الألوسي:٢٥/٢٠٩.\nكيف يتعامل العاقل مع ما تهواه نفسه وتشتهيه من المعاصي والمنكرات؟\nأَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمٖ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ فَمَن يَهۡدِيهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ٢٣\nوهذه الآية أصل في التحذير من أن يكون الهوى الباعث للمؤمنين على أعمالهم، ويتركوا اتباع أدلة الحق. فإذا كان الحق محبوبًا لأحد فذلك من التخلق بمحبة الحق تبعًا للدليل؛ مثل ما يهوى المؤمن الصلاة والجماعة وقيامَ رمضان وتلاوة القرآن، وفي الحديث: «أرِحنا بها يا بلال» يعني الإقامة للصلاة... وأَما اتباع الأمرِ المحبوب لإِرضاء النفسِ دون نظَرٍ في صلاحه أَو فَساده فَذلكَ سبب الضلال وسوء السيرة. ابن عاشور:٢٥/٣٥٩.\nقررت الآية الكريمة أصلًا مهمًا في اتباع هوى النفس؛ ما هو؟\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ٢٥\nلم يجبهم إلى إحياء آبائهم إكرامًا لهذه الأمة، لشرف نبيها -عليه أفضل الصلاة والسلام-؛ لأنَّ سنته الإلهية جرت بأنَّ مَن لم يؤمن بعد كشف الأمر بإيجاد الآيات المقترحات أهلكه، كما فعل بالأمم الماضية. البقاعي:٧/١٠٦.\nمن إكرام هذه الأمة عدم الاستجابة لمقترحات المشركين من إحياء آبائهم؛ وضِّح ذلك.\nوَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ مَّا كَانَ حُجَّتَهُمۡ إِلَّآ أَن قَالُواْ ٱئۡتُواْ بِـَٔابَآئِنَآ إِن كُنتُمۡ صَٰدِقِينَ ٢٥\nقال الزمخشري: \"فإن قلت لم سمي قولهم حجة، وليس بحجة؟ قلت: لأنهم أدلوا به كما يدلي المحتج بحجته، وساقوه مساقها؛ فسميت حجة على سبيل التهكم. أو لأنه في حسبانهم وتقديرهم حجة. أو...كأنه قيل: ما كان حجتهم إلا ما ليس بحجة. والمراد نفي أن تكون لهم حجة البتة\". القرطبي:١٩/١٦٧.\nلم سمى الله تعالى قولهم حجة؟\nوَتَرَىٰ كُلَّ أُمَّةٖ جَاثِيَةٗۚ\nعلى رُكَبها خوفًا وذعرًا، وانتظارًا لحكم الملك الرحمن. السعدي:٧٧٨.\nما سبب جثو الأمم يوم القيامة؟\nفَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُدۡخِلُهُمۡ رَبُّهُمۡ فِي رَحۡمَتِهِۦۚ ذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِينُ ٣٠\nوابتدىء في التفصيل بوصف حال المؤمنين مع أن المقام للحديث عن المبطلين في قوله: ﴿يَوۡمَئِذٍ يَخۡسَرُ ٱلۡمُبۡطِلُونَ﴾ تنويهًا بالمؤمنين، وتعجيلًا لمسرتهم، وتعجيلًا لمساءة المبطلين. ابن عاشور:٢٥/٣٧١.\nمظاهر إكرام الله تعالى للمؤمنين متعددة، بيّن أحدها من خلال الآية الكريمة."],[502,"§الجاثية ، الأحقاف\nwords\nوَحَاقَ بِهِمنَزَلَ بِهِم.\nنَنسَاكُمنَترُكُكُم فِي العَذَابِ.\nوَمَأوَاكُمُمَنزِلُكُم وَمَقَرُّكُم.\nوَغَرَّتكُمُخَدَعَتكُم.\nوَلاَ هُم يُستَعتَبُونَلاَ يُطلَبُ مِنهُم أَن يُرضُوا رَبَّهُم بِالتَّوبَةِ، وَالطَّاعَةِ.\nلَهُم شِركٌشِركَةٌ وَنَصِيبٌ مَعَ اللهِ تَعَالَى فِي خَلقِ السَّمَاوَاتِ.\ndeeds\nقل: \"اللهم أعني على ذكرك وشكرك وحسن عبادتك\".\nقل عندما تصبح: \"سبحان الله وبحمده\" مائة مرة، وكذلك عندما تُمسي.\nاركع في صلاتك اليوم ركوعًا طويلًا مسبحًا الله بما له من صفات التعظيم.\nguid\nطول الأمل والاغترار بالدنيا من أسباب حلول العقاب.\nتذكر أن كل ما أخفيته يتبدى ويظهر يوم القيامة.\nابتعد عن خُلُق الاستهزاء والسخرية خاصة بشعائر الدين فعواقبها وخيمة.\nrefl\nوَغَرَّتۡكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ\nخدعتكم بأباطيلها وزخارفها، فظننتم أن ليس ثَمَّ غيرها وأن لا بعث. القرطبي:١٩/١٧٣.\nكيف غرتهم الدنيا؟\nفَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ٣٦\nأعاد ذكر الرب تنبيهًا على أن حفظه للخلق وتربيته لهم ذو ألوان بحسب شؤون الخلق؛ فحفظه لهذا الجزء على وجه يغاير حفظه لجزء آخر، وحفظه للكل من حيث هو كل على وجه يغاير حفظه لكل جزء على حدته، مع أن الكل بالنسبة إلى تمام القدرة على حد سواء. البقاعي:١٨/١١٦.\nلماذا أعاد ذكر الرب؟\nفَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَٰوَٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَٰلَمِينَ ٣٦ وَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ\nوالعبادة مبنية على ركنين: محبة الله، والذل له؛ وهما ناشئان عن العلم بمحامد الله وجلاله وكبريائه. السعدي:٧٧٩.\nما أركان العبادة وممَ تنشأ؟\nوَلَهُ ٱلۡكِبۡرِيَآءُ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٣٧\nعن أبي هريرة -رضي الله عنه- قال: قال رسول الله -صلى الله عليه وسلم-: «يقول الله -تبارك وتعالى-: الكبرياء ردائي، والعظمة إزاري؛ فمن نازعني واحدًا منهما ألقيته في النار». الشوكاني:٥/١٢.\nبيّن اختصاص الله سبحانه بالكبرياء من السنة النبوية.\nتَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ٢ مَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۚ\nلما بين إنزال كتابه المتضمن للأمر والنهي ذكر خلقه السماوات والأرض، فجمع بين الخلق والأمر؛ ﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُ﴾. السعدي:٧٧٩.\nلماذا ذكر خلق السموات والأرض وما بينهما بعد ذكر تنزيل الكتاب؟\nوَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ٥\nمعناها: لا أحد أضل ممن يدعو إلهًا لا يستجيب له؛ وهي الأصنام؛ فإنها لا تسمع ولا تعقل، ولذلك وصفها بالغفلة عن دعائهم لأنها لا تسمعه. ابن جزي:٢/٣٣١.\nدعاء من لا يسمع نوع من الجهل والضلال؛ وضح ذلك من الآية.\nوَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ٥\nوإنَّما عنى بوصفها بالغفلة: تمثيلها بالإنسان الساهي عما يقال له؛ إذ كانت لا تفهم مما يقال لها شيئًا كما لا يفهم الغافل عن الشيء ما غفل عنه. وإنَّما هذا توبيخ من الله لهؤلاء المشركين لسوء رأيهم، وقبح اختيارهم في عبادتهم من لا يعقل شيئًا ولا يفهم. الطبري:٢٢/٩٥.\nما وجه وصف الآلهة التي يدعوها المشركون بالغفلة؟ وما المراد منه؟"],[503,"§الأحقاف\nwords\nافتَرَاهُاختَلَقَهُ.\nتُفِيضُونَ فِيهِتَقُولُونَ فِي القُرآنِ.\nبِدعًا مِنَ الرُّسُلِأَوَّلَ رُسُلِ اللهِ إِلَى خَلقِهِ.\nأَرَأَيتُمأَخبِرُونِي.\nوَشَهِدَ شَاهِدٌكَعَبدِ اللهِ بنِ سَلاَمٍ رضي الله عنه.\nإِفكٌ قَدِيمٌكَذِبٌ مَأثُورٌ عَنِ النَّاسِ الأَقدَمِينَ.\nاستَقَامُواثَبَتُوا عَلَى الإِيمَانِ وَالطَّاعَةِ.\ndeeds\nابحث عن بدعة موجودة بين الناس وانصح بعض من حولك بتركها.\nابحث عن خير واسبق غيرك إلى فعله هذا اليوم.\nقل: \"ربي الله\"، ثم اجتهد في تطبيق جميع العبادات في ذلك اليوم على أتم وجه.\nguid\nالرسول ليس له إلا أن يتبع ما يوحى إليه، فنحن من باب أولى.\nالإعجاب بالنفس سبب من أسباب البعد عن الهداية.\nفضل الاستقامة على الدين وأهميتها.\nrefl\nكَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٨\nففي هذا الختام ترغيب للنبي في الصفح عنهم فيما نسبوه إليه في افتتاحها من الافتراء، وندب إلى الإحسان إليهم، وترغيب لهم في التوبة. البقاعي:١٨/١٣٢.\nما دلالة ختم الآية بصفتي (الغفور) و(الرحيم) له سبحانه؟\nكَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ٨\nهذا تهديد لهم ووعيد أكيد، وترهيب شديد. وقوله -جلّ وعلا-: ﴿وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ﴾ ترغيب لهم إلى التوبة والإنابة؛ أي: ومع هذا كله إن رجعتم وتبتم تاب عليكم وعفا عنكم وغفر ورحم. ابن كثير:٤/١٥٧.\nدائمًا ما يقرن الله بين الترغيب والترهيب في كتابه؛ بيّن ذلك من خلال هذه الآية.\nقُلۡ مَا كُنتُ بِدۡعٗا مِّنَ ٱلرُّسُلِ\n(مِن) ابتدائية؛ أي ما كنت آتيًا منهم بديعًا غير مماثل لهم؛ فكما سمعتم بالرسل الأولين أخبروا عن رسالة الله إياهم فكذلك أنا؛ فلماذا يعجبون من دعوتي؟! وهذه الآية صالحة للرد على نصارى زماننا الذين طعنوا في نبوته بمطاعن لا منشأ لها إلا تضليلٌ وتمويه على عامتهم؛ لأن الطاعنين ليسوا من الغباوة بالذين يخفى عليهم بهتانهم. ابن عاشور:٢٦/ ١٧.\nكيف ترد بهذه الآية الكريمة على النصارى؟\nوَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِۚ\nوأما أهل السنة والجماعة فيقولون في كل فعل وقول لم يثبت عن الصحابة -رضي الله عنهم- هو بدعة؛ لأنه لو كان خيرًا لسبقونا إليه؛ لأنهم لم يتركوا خصلة من خصال الخير إلا وقد بادروا إليها. ابن كثير:٤/١٥٩.\nما الفرق بين قول المشركين وقول أهل السنة والجماعة في الصحابة؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٣\nالذين جمعوا بين التوحيد الذي هو خلاصة العلم، والاستقامة في الدِّين التي هي منتهى العمل. الألوسي:٢٥/٢٤٠.\nما المقصود بقوله تعالى: ﴿قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ﴾؟\nإِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ١٣\nإشارة إلى أن هيبته بالنظر إلى جلاله وقهره وجبروته وكبره وكماله لا تنتفي، ويحصل للإنسان باستحضارها إخبات وطمأنينة ووقار وسكينة يزيده في نفسه جلالًا ورفعة وكمالًا؛ فالمنفي خوف يقلق النفس. البقاعي:١٨/١٤٤.\nما نوع الخوف المنفي هنا؟\nأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ١٤\nالعباد لا يزالون مقصرين محتاجين إلى عفوه ومغفرته؛ فلن يدخل أحد الجنة بعمله، وما من أحد إلا وله سيئات يحتاج فيها إلى مغفرة الله لها؛ ﴿وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُواْ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَآبَّةٍ﴾ [فاطر: ٤٥]. وقوله -صلى الله عليه وسلم-: «لن يدخل أحد منكم الجنة بعمله» لا يناقض قوله تعالى: ﴿جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ﴾... فالعمل لا يقابل الجزاء وإن كان سببًا للجزاء؛ ولهذا من ظن أنه قام بما يجب عليه، وأنه لا يحتاج إلى مغفرة الرب تعالى وعفوه فهو ضال. ابن تيمية:٥/٥٤٩.\nكيف تجمع بين قوله -صلى الله عليه وسلم-: «لن يدخل أحد منكم الجنة بعمله» وقـوله تعالى: ﴿جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ﴾؟"],[504,"§الأحقاف\nwords\nوَفِصَالُهُفِطَامُهُ.\nأَوزِعنِيأَلهِمنِي.\nأُفٍّ لَكُمَاقُبحًا لَكُمَا.\nعَذَابَ الهُونِعَذَابَ الخِزيِ وَالهَوَانِ.\ndeeds\nخصص اليوم وقتًا لوالديك لتدخل السرور والأنس عليهما، وقدم هدية لهما ولو يسيرة.\nتخيل اليوم أنك حملت شيئًا وزنه خمسة كيلو جرامات لمدة يوم كامل، ثم تصور مقدار معاناة أمك بحملك.\nادعُ اليوم في سجودك بهذا الدعاء.\nguid\nتقلبت أمك في تربيتك بين معاناة الحمل والولادة والرضاع والإطعام والنظافة والمرض والهداية، فهل تستطيع أن توفيها حقها؟\nمن عق والديه بأدنى درجات الإيذاء فيخشى دخوله في وعيد قوله تعالى.\nكثرة الترف تورث الكبر والغفلة.\nrefl\nوَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ\nإشارة إلى أن حق الأم آكد من حق الأب؛ لأنها حملته بمشقة، ووضعته بمشقة، وأرضعته هذه المدة بتعب ونصب، ولم يشاركها الأب في شيء من ذلك. الشوكاني:٥/١٨.\nقررت الآية بر الوالدين جميعًا، ولكنها أشارت إلى أن حق الأم آكد، بين ذلك.\nحَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ١٥\nفيه إرشاد لمن بلغ الأربعين أن يجدد التوبة والإنابة إلى الله -عز وجل- ويعزم عليها. ابن كثير:٤/١٦٠.\nما الإرشاد الذي تدل عليه الآية لمن بلغ أربعين سنة؟\nحَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ\nوإنَّما خص زمان بلوغه الأشد لأنه زمن يكثر فيه الكلف بالسعي للرزق؛ إذ يكون له فيه زوجة وأبناء، وتكثر تكاليف المرأة؛ فيكون لها فيه زوج وبيت وأبناء، فيكونان مظنة أن تشغلهما التكاليف عن تعهد والديهما والإحسان إليهما، فنُبِّها بأن لا يفتُرا عن الإحسان إلى الوالدين. ابن عاشور:٢٦/٣٢.\nلماذا خص زمان بلوغ الأشد في الآية الكريمة؟\nأَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ\nوالنِعَم على الوالدين نِعَمٌ على أولادهم وذريتهم؛ لأنهم لا بد أن ينالهم منها ومن أسبابها وآثارها، خصوصًا نِعَم الدين؛ فإن صلاح الوالدين بالعلم والعمل من أعظم الأسباب لصلاح أولادهم. السعدي:٧٨١.\nلماذا يشكر الإنسان النعم التي أنعمها الله على والديه؟\nوَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا\nفالمؤمن لا يُذهِب طيباتِه في الدنيا، بل إنه يترك بعض طيباته للآخرة. وأمَّا الكافر فإنه لا يؤمن بالآخرة؛ فهو حريص على تناول حظوظه كلها في الدنيا. ابن القيم:٢/٤٥٠.\nما الفرق بين موقف المؤمن وموقف الكافر من ملذات الحياة الدنيا؟\nوَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا\nوالآية في الكفار بدليل قوله: ﴿يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ﴾، وهي مع ذلك واعظة لأهل التقوى من المؤمنين؛ ولذلك قال عمر لجابر بن عبد الله وقد رآه اشترى لحمًا: \"أما تخشى أن تكون من أهل هذه الآية؟\". ابن جزي:٢/٣٣٥.\nهل يتعظ المسلم بالآيات التي نزلت في الكفار؟ وكيف؟\nفَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ ٢٠\nأُريد بالاستكبار الترفع عن الإيمان، وبالفسق معاصي الجوارح، وقدَّمَ ذنب القلب على ذنب الجوارح؛ إذ أعمال الجوارح ناشئة عن مراد القلب. الألوسي:٢٥/٢٥٠.\nفي الآية تقديم ذنب القلب على ذنب الجوارح؛ وضّح ذلك، وأيهما أخطر؟"],[505,"§الأحقاف\nwords\nبِالأَحقَافِاسمُ مَوقِعِهِم؛ وَهُوَ فِي جَنُوبِ جَزِيرَةِ العَرَبِ.\nلِتَأفِكَنَالِتَصرِفَنَا.\nعَارِضًاسَحَابًا عَرَضًا فِي أُفُقِ السَّمَاءِ.\nمَكَّنَّاهُمأَقدَرنَاهُم، وَبَسَطنَا لَهُم.\nوَحَاقَنَزَلَ.\nقُربَانًايَتَقَرَّبُونَ بِهَا إِلَى رَبِّهِم.\ndeeds\nاحفظ دعاء الريح والمطر المأثور: \"اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أرسلت به\"، واقرأه عند رؤيتهما.\nاعمل ثلاث طاعاتٍ: الأولى متعلقة بالسمع، والثانية بالبصر، والثالثة بالفؤاد.\nشاهد صورًا عن الآثار المتبقية من الأمم الماضية، وسجل العبر التي تأثرت بها.\nguid\nقصص الأنبياء تسلية للنبي، ولمن سار على نهجه.\nقوم عاد لجهلهم وكبرهم استبشروا بالسحاب الذي كان فيه هلاكهم.\nلا ينفع التطور العلمي والحضاري والعمراني إذا نزل عقاب الله تعالى.\nrefl\n۞وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ\nبضرب الأمثال وقصص مَن تَقَدَّم يُعرف قبح الشيء وحسنه؛ فقال سبحانه لرسوله -صلّى الله عليه وسلّم-: ﴿۞وَٱذۡكُرۡ أَخَا عَادٍ﴾. الألوسي: ٢٥/٢٥١.\nما فائدة التذكير بقصة عاد؟\nقَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ٢٣\nوإنَّما زيد ( قومًا ) ولم يقتصر على ( تجهلون ) للدلالة على تمكن الجهالة منهم حتى صارت من مقوّمات قوميتهم، وللدلالة على أنها عمت جميع القبيلة كما قال لوط لقومه: ﴿أَلَيۡسَ مِنكُمۡ رَجُلٌ رَّشِيدٌ﴾ [هود: ٧٨ ]. ابن عاشور: ٢٦/٤٨\nما دلالة كلمة (قومًا) في الآية الكريمة؟\nفَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ ٢٤\nأخرج مسلم عن عائشة -رضي الله تعالى عنها- قالت: كان رسول الله إذا عصفت الريح قال: «اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أرسلت به»، فإذا أخيلت السماء تغير لونه وخرج ودخل، وأقبل وأدبر، فإذا مطرت سُرِّي عنه؛ فسألته؛ فقال -عليه الصلاة والسلام-: «لا أدري لعله كما قال قوم عاد: ﴿هَٰذَا عَارِضٌ مُّمۡطِرُنَاۚ﴾». الألوسي: ٢٥/٢٥٦.\nما الدعاء المستحب عند رؤية الريح أو السحاب مقبلة؟\nوَلَقَدۡ مَكَّنَّٰهُمۡ فِيمَآ إِن مَّكَّنَّٰكُمۡ فِيهِ\nأي: ولقد مكنّا عادًا كما مكناكم يا هؤلاء المخاطبون؛ أي: فلا تحسبوا أن ما مكناكم فيه مختص بكم، وأنه سيدفع عنكم من عذاب الله شيئًا، بل غيركم أعظم منكم تمكينًا، فلم تغن عنهم أموالهم ولا أولادهم ولا جنودهم من الله شيئًا. السعدي: ٧٨٣.\nالقوة المادية لا تنفع شيئًا إذا أراد الله العقوبة لأهلها؛ وضّح ذلك.\nوَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ\nوفائدة قوله: (وجعلنا لهم سمعًا وأبصارًا وأفئدة) أنهم لم ينقصهم شيء من شأنه يُخِلّ بإدراكهم الحق لولا العناد، وهذا تعريض بمشركي قريش؛ أي أنكم حرمتم أنفسكم الانتفاع بسمعكم وأبصاركم وعقولكم كما حرموه. ابن عاشور: ٢٦/٥٣.\nما فائدة قوله تعالى: (وجعلنا لهم سمعًا وأبصارًا وأفئدة)؟\nوَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ\nوهذه الآية وأمثالها تدل على أن السمع والأبصار والأفئدة لا تنفع صاحبها مع جحده بآيات الله، فتبين أن العقل الذي هو مناط التكليف لا يحصل بمجرده الإيمان النافع والمعرفة المنجية من عذاب الله. ابن تيمية: ٥/٥٥٠.\nالهداية ليست مجرد ثمرة للعقل، ولكنها منّة من الله سبحانه؛ وضّح ذلك.\nفَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۖ بَلۡ ضَلُّواْ عَنۡهُمۡۚ\nأي فهلا نصرهم آلهتهم التي تقربوا بها بزعمهم إلى الله لتشفع لهم -حيث قالوا: هؤلاء شفعاؤنا عند الله- ومنعتهم من الهلاك الواقع بهم. الشوكاني: ٥/٢٤.\nالمتقرب إليهم ضعفاء في الدنيا والآخرة، بين الإجابة من خلال الآية."],[506,"§الأحقاف\nwords\nصَرَفنَابَعَثنَا وَوَجَّهنَا نَحوَكَ.\nقُضِيَفَرَغَ رَسُولُ اللهِ صلّى الله عليه وسلّم مِن تِلاَوَتِهِ.\nمُنذِرِينَمُحَذِّرِينَ مِن بَأسِ اللهِ.\nوَيُجِركُميُنقِذكُم.\nيَعيَ بِخَلقِهِنَّلَم يَعجِز عَن خَلقِهِنَّ، وَلَم يَتعَب بِهِ.\nبَلاَغٌهَذَا تَبلِيغٌ مِنَ اللهِ لَهُم.\ndeeds\nتذكر عبادةً أمرك بها داعيةٌ أو ناصح لك وقم بتنفيذها.\nاقرأ القرآن وحدك وارفع به صوتك؛ فربما استمع إليك ملائكة أو جن فيزيد أجرك.\nاستمع إلى آية من كتاب الله ثم اعمل بها لعلك تكون من أهل القرآن.\nguid\nالمؤمن يحمل هم تعليم الغير ونفعهم.\nمن خلق السماوات والأرض فهو قادر على إعادة الإنسان بعد موته.\nالصبر من خلُق الأنبياء والمرسلين، وهو من أسباب الفلاح في الدنيا والآخرة.\nrefl\nوَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ ٢٩\nأي: استمعوا، وهذا أدب منهم.... ﴿وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ﴾ أي: رجعوا إلى قومهم فأنذروهم ما سمعوه من رسول الله -صلى الله عليه وسلم-؛ كقوله: ﴿لِّيَتَفَقَّهُواْ فِي ٱلدِّينِ وَلِيُنذِرُواْ قَوۡمَهُمۡ إِذَا رَجَعُوٓاْ إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَرُونَ﴾ [التوبة: ١٢٢]. وقد استدل بهذه الآية على أنه في الجن نُذُرٌ، وليس فيهم رسلٌ؛ ولا شك أن الجن لم يبعث الله تعالى منهم رسولًا. ابن كثير:٤/١٧٢.\nما الأدب الذي فعله الجن عند استماعهم للقرآن؟ وهل من الجن رسل؟\nقَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ\nولم يذكروا عيسى؛ لأن عيسى -عليه السلام- أنزل عليه الإنجيل فيه مواعظ وترقيقات وقليل من التحليل والتحريم، وهو في الحقيقة كالمتمم لشريعة التوراة، فالعمدة هو التوراة؛ فلهذا قالوا: ﴿أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ﴾. وهكذا قال ورقة بن نوفل حين أخبره النبي -صلى الله عليه وسلم- بقصة نزول جبريل -عليه الصلاة والسلام- أول مرة؛ فقال: \"بخ بخ، هذا الناموس الذي كان يأتي موسى\". ابن كثير ٤/١٧٣.\nلماذا قالت الجن: ﴿أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ﴾، ولم يقولوا: \"أنزل من بعد عيسى\"؟\nمُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ ٣٠ يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ\nلَمَّا مدحوا القرآن وبينوا محله ومرتبته دعوهم إلى الإيمان به. السعدي:٧٨٣.\nفي ترتيب كلام الجن فائدة دعوية مهمة، وضحها.\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۢ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ ٣٥\nالعزم المحمود في الدين: العزم على ما فيه تزكية النفس وصلاح الأمة، وقوامه الصبر على المكروه، وباعثه التقوى، وقوته شدة المراقبة بأن لا يتهاون المؤمن عن محاسبته نفسه؛ قال تعالى: ﴿وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ﴾ [آل عمران:١٨٦]. ابن عاشور:٢٦/٦٧.\nما مقومات العزم المحمود؟\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ\n﴿أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ﴾ هم: نوح وإبراهيم وموسى وعيسى ومحمد -عليهم الصلاة والسلام-؛ وعلى هذا القول فالرسل الذين أُمِر رسول الله أن يصبر كما صبروا أربعة، فصار هو خامسهم. الشنقيطي: ٧/٢٤١.\nمن أولو العزم من الرسل -عليهم الصلاة والسلام-؟\nفَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ\nلما أمره بالصبر الذي من أعلى الفضائل، نهاه عن العجلة التي هي من أمهات الرذائل، ليصح التحلي بفضيلة الصبر الضامنة للفوز والنصر، فقال: ﴿وَلَا تَسۡتَعۡجِل لَّهُمۡۚ﴾ أي: تطلب العجلة وتوجدها بأن تفعل شيئًا مما يسوءهم في غير حينه. البقاعي:١٨/١٩١.\nبينت الآية أن كمال الداعية يحصل بصفتين، ما هما؟\nكَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۢ\nلأنه ينسيهم شدة ما ينزل بهم من عذابه قدر ما كانوا في الدنيا لبثوا، ومبلغ ما فيها مكثوا من السنين والشهور؛ كما قال -جل ثناؤه-: ﴿قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ * قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ﴾ [المؤمنون: ١١٢-١١٣]. الطبري:٢٢/١٤٦.\nما الذي جعل الكفار يعتقدون قِصَرَ مكثهم في الدنيا؟"],[507,"§محمد\nwords\nفَضَربَ الرِّقَابِاضرِبُوا مِنهُمُ الأَعنَاقَ.\nأَثخَنتُمُوهُمأَضعَفتُمُوهُم بِكَثرَةِ القِتَالِ، وَكَسَرتُم شَوكَتَهُم.\nفَشُدُّوا الوَثَاقَأَحكِمُوا قَيدَ الأَسرَى.\nمَنًّاتَمُنُّونَ عَلَيهِم بِإِطلاَقِ الأَسرَى مِن غَيرِ عِوَضٍ.\ndeeds\nسَل الله تعالى أن يصلح لك عملك وأن يتقبله منك.\nاقرأ قصة غزوة بدر الكبرى وتأمل كيف ضحى الصحابة لنصرة دين الله، وكيف أيدهم الله.\nانصر الله في موطنٍ من المواطن، بأن تدافع عن شخصٍ يغتابه آخر، أو تُذَكِّر مذنبًا بالله -عز وجل-.\nguid\nالإيمان والعمل الصالح يثمران تكفير السيئات وصلاح القلوب.\nالتمسك بالدين في وقت الفتن وغلبة الشهوات والشبهات والدفاع عنه من وسائل نصرة الله ورسوله.\nنصرة الإسلام تقتضي العمل بأوامر الشرع واجتناب نواهيه.\nrefl\nوَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ\nفإنه تعالى على كل شيء قدير، وقادر على أن لا ينتصر الكفار في موضع واحد أبدًا، حتى يبيد المسلمون خضراءهم. ﴿وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٍۗ﴾ ليقوم سوق الجهاد، ويتبين بذلك أحوال العباد؛ الصادق من الكاذب، وليؤمن من آمن إيمانًا صحيحًا عن بصيرة، لا إيمانًا مبنيًا على متابعة أهل الغلبة؛ فإنه إيمان ضعيف جدًا لا يستمر لصاحبه عند المحن والبلايا. السعدي:٧٨٥.\nما الابتلاء الذي ينبني على انتصار المشركين على المسلمين في بعض المواقع؟\nوَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ ٤ سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ ٥\n﴿وَيُصۡلِحُ بَالَهُمۡ﴾ أي: موضع فِكرهم؛ فيجعله مهيأ لكل خير، بعيدًا عن كل شر، آمنًا من المخاوف، مطمئنًا بالإيمان بما فيه من السكينة، فإذا قتل أحد في سبيله تولى -سبحانه وتعالى- ورثته بأحسن من تولي المقتول لو كان حيًا. البقاعي:٧/١٥٣.\nمامعنى ﴿وَيُصۡلِحُ بَالَهُمۡ﴾؟\nوَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ ٦\nأي بَيَّن لهم منازلهم في الجنة حتى يهتدوا إلى مساكنهم لا يخطؤون ولا يستدلون عليها أحدًا؛ كأنهم سكانها منذ خلقوا، فيكون المؤمن أهدى إلى درجته وزوجته وخدمه منه إلى منزله وأهله في الدنيا، هذا قول أكثر المفسرين. البغوي:٤/١٥٤.\nكيف عرَّف الله تعالى الجنة لأهلها؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ٧\nفالذين يرتكبون جميع المعاصي ممن يتسمون باسم المسلمين، ثم يقولون: إن الله سينصرنا مغررون لأنهم ليسوا من حزب الله الموعودين بنصره كما لا يخفى. ومعنى نصر المؤمنين لله: نصرهم لدينه ولكتابه، وسعيهم وجهادهم في أن تكون كلمته هي العليا، وأن تقام حدوده في أرضه، وتمتثل أوامره، وتجتنب نواهيه. الشنقيطي:٧/٢٥٢.\nما معنى نصر المؤمنين لله تعالى؟ وهل الذين يرتكبون المعاصي جديرون بنصرة الله لهم؟\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ٧ وَٱلَّذِينَ كَفَرُواْ فَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ ٨ ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ٩\nوهذا وعيد للأمة بأنها إن تخلت عن نصر الله والجهاد في سبيله، والأمر بالمعروف والنهي عن المنكر وَكَلَها سبحانه إلى نفسها، وتخلَّى عن نصرها، وسلَّطَ عليها عدوها. ولقد وُجِد بعض ذلك؛ من تسلط الفسقة، لمَّا وُجِد التهاون في بعض ذلك والتواكل فيه. البقاعي:٧/١٥٥.\nما عقوبة الإعراض عن أوامر الله تعالى، وكراهيتها؟\n۞أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ\nكل موضع أمر الله سبحانه فيه بالسير في الأرض، سواء كان السير الحسي على الأقدام والدواب، أو السير المعنوي بالتفكير والاعتبار، أو كان اللفظ يعمهما... فإنه يدل على الاعتبار والحذر أن يحل بالمخاطبين ما حل بأولئك. ابن القيم:٢/٤٥٤.\nما الحكمة من أمر الله عباده أن يسيروا في الأرض؟\nوَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ ١١\n﴿لَا مَوۡلَىٰ لَهُمۡ﴾: يهديهم إلى سبل السلام، ولا ينجيهم من عذاب الله وعقابه، بل أولياؤهم الطاغوت؛ يخرجونهم من النور إلى الظلمات. السعدي:٧٨٦.\nإذا كان الكفار أولياؤهم الطاغوت فما المقصود بأنه لا مولى لهم؟"],[508,"§محمد\nwords\nمَثوىًمَأوىً، وَمسكَنٌ.\nغَيرِ آسِنٍغَيرِ مُتَغَيِّرٍ، وَلاَ مُنتِنٍ.\nآنِفًاالآنَ.\nجَاءَ أَشرَاطُهَاظَهَرَت عَلاَمَاتُهَا.\nفَأَنَّىمِن أَينَ لَهُم؟!\nمُتَقَلَّبَكُمتَصَرُّفَكُم فِي يَقَظَتِكُم نَهَارًا.\nوَمَثوَاكُممُستَقَرَّكُم فِي نَومِكُم لَيلًا.\ndeeds\nسم الله عند الأكل، واحمده في آخره، ولا تأكل كما تأكل الأنعام بدون التسمية.\nاقرأ كتابًا في صفة وضوء النبي وصلاته حتى تعبد الله على بينة.\nاستغفر الله من ذنوبك، ثم سل الله أن يغفر للمؤمنين والمؤمنات ذنوبهم.\nguid\nانظر واعتبر في إهلاك الله تعالى للقرى الظالمة.\nاستعد ليوم القيامة بالعمل الصالح.\nأهمية العلم فهو الذي يجعلك تعمل على بصيرة وهدى.\nrefl\nإِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ\nأنساهم دخولهم غصص ما كانوا فيه في الدنيا من نكد العيش ومعاناة الشدائد، وضموا نعيمها إلى ما كانوا فيه في الدنيا من نعيم الوصلة بالله، ثم لا يحصل لهم كدر ما أصلًا، وهي مأواهم لا يبغون عنها حولًا، وهذا في نظير ما زوي عنهم من الدنيا وضيق فيها عيشهم نفاسةً منهم عنها، حتى فرغهم لخدمته وألزمهم حضرته حبًّا لهم وتشريفًا لمقاديرهم. البقاعي:١٨/٢١٤.\nما أثر دخول المؤمنين الجنة؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\n﴿وَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ﴾: في الدنيا كأنهم أنعام، ليس لهم همة إلا بطونهم وفروجهم، ساهون عما في غدهم. وقيل: المؤمن في الدنيا يتزود، والمنافق يتزين، والكافر يتمتع. القرطبي:١٩/٢٥٧.\nما أكبر همّ للكفار في الدنيا؟ ومالفرق بين همّة كل من المؤمن والكافر والمنافق؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\nوالذين جحدوا توحيد الله، وكذبوا رسوله -صلى الله عليه وسلم- يتمتعون في هذه الدنيا بحطامها ورياشها وزينتها الفانية... فمثلهم في أكلهم ما يأكلون فيها من غير علم منهم بذلك وغير معرفة، مثل الأنعام من البهائم المسخرة التي لا همة لها إلا في الاعتلاف دون غيره. الطبري:٢٢ / ١٦٤.\nما وجه الشبه بين الكفار والبهائم في هذه الدنيا؟\nوَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ١٢\n﴿كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ﴾: أكل التذاذ ومرح؛ من أي موضع كان وكيف كان الأكل، في سبعة أمعاء؛ أي في جميع بطونهم، من غير تمييز للحرام من غيره؛ لأن الله تعالى أعطاهم الدنيا، ووسع عليهم فيها، وفرغهم لها حتى شغلهم عنه. البقاعي:١٨/٢١٤.\nما دلالة إعطاء الإنسان نعيم الدنيا وحرمانه العبادة؟\nفَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ ١٩\nعن أبي موسى قال: قال رسول اللّه: «ما أصبحت غداة قط إلا استغفرت اللّه فيها مائة مرة». عن ابن عمر -رضي اللّه تعالى عنهما- قال: إنا كنا لنَعُدُّ لرسول اللّه في المجلس يقول: «رب اغفر لي وتب علي إنك أنت التواب الرحيم» مائة مرة. الألوسي:٢٥/٢٩٤.\nاذكر مثالًا على تدبر النبي -صلى الله عليه وسلم- للقرآن وعمله به.\nفَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ\nعن سفيان بن عيينة أنه سئل عن فضل العلم فقال: \"ألم تسمع قوله حين بدأ به: ﴿فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ﴾؛ فأمر بالعمل بعد العلم، وقال: ﴿ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٌ...﴾ إلى قوله: ﴿سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ...﴾ [الحديد: ٢٠- ٢١]، وقال: ﴿ٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٌ﴾ [الأنفال: ٢٨] ثم قال بعد: ﴿فَٱحۡذَرُوهُمۡ﴾ [التغابن: ١٤]، وقال تعالى: ﴿وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ...﴾ [الأنفال: ٤١]، ثم أمر بالعمل بعد\". القرطبي:١٩/٢٦٧.\nبيّن كيف دلت الآية على فضل العمل بعد العلم.\nوَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ\nوإذا كان مأمورًا بالاستغفار لهم المتضمن لإزالة الذنوب وعقوباتها عنهم، فإن من لوازم ذلك النصح لهم، وأن يحب لهم من الخير ما يحب لنفسه، ويكره لهم من الشر ما يكره لنفسه، ويأمرهم بما فيه الخير لهم، وينهاهم عما فيه ضررهم، ويعفو عن مساويهم ومعايبهم، ويحرص على اجتماعهم اجتماعًا تتألف به قلوبهم، ويزول ما بينهم من الأحقاد المفضية للمعاداة والشقاق الذي به تكثر ذنوبهم ومعاصيهم. السعدي:٧٨٧- ٧٨٨.\nما لوازم الاستغفار للمؤمنين والمؤمنات؟"],[509,"§محمد\nwords\nمَرَضٌشَكٌّ، وَنِفَاقٌ.\nالمَغشِيِّ عَلَيهِالمُغمَى عَلَيهِ مِن شِدَّةِ الخَوفِ.\nعَزَمَ الأَمرُوَجَبَ القِتَالُ.\nفَهَل عَسَيتُملَعَلَّكُم.\nتَوَلَّيتُمأَعرَضتُم عَنِ الإِيمَانِ.\nارتَدُّوا عَلَى أَدبَارِهِمرَجَعُوا كُفَّارًا.\nسَوَّلَ لَهُمزَيَّنَ لَهُم خَطَايَاهُم.\nإِسرَارَهُممَا يُخفُونَهُ، وَيُسِرُّونَهُ.\nأَضغَانَهُمأَحقَادَهُم.\ndeeds\nزُر أحد أقاربك أو اتصل به حتى تحافظ على صلة الرحم.\nاقرأ هذا الوجه من القرآن بتدبر ثم استخرج منه ثلاث فوائد غير ما ذكر.\nادع الله أن يجـعل قلبك سليمًا ويطـهره من النفـاق والرياء والعجـب.\nguid\nكن من الصادقين مع الله.\nخطورة قطيعة الأرحام.\nما أسر عبد سريرةً إلا الله قادر على إظهارها سبحانه.\nrefl\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢ أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ٢٣\nوقد علم من هذا أن من أمر بالمعروف، وجاهد أهل المنكر أمن الإفساد في الأرض وقطيعة الرحم، ومن تركه وقع فيهم. البقاعي:٧/١٦٩.\nما عاقبة ترك الأمر بالمعروف والنهي عن المنكر وترك الجهاد في سبيل الله على المجتمع المسلم؟\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢\nالرحم على وجهين: عامة وخاصة؛ فالعامة: رحم الدين؛ ويجب مواصلتها بملازمة الإيمان، والمحبة لأهله، ونصرتهم، والنصيحة، وترك مضارتهم، والعدل بينهم، والنصفة في معاملتهم، والقيام بحقوقهم الواجبة؛ كتمريض المرضى، وحقوق الموتى من: غسلهم والصلاة عليهم ودفنهم، وغير ذلك من الحقوق المترتبة لهم. وأمَّا الرحم الخاصة -وهي رحم القرابة من طرفي الرجل أبيه وأمه-: فتجب لهم الحقوق الخاصة وزيادة؛ كالنفقة، وتفقد أحوالهم، وترك التغافل عن تعاهدهم في أوقات ضروراتهم، وتتأكد في حقهم حقوق الرحم العامة، حتى إذا تزاحمت الحقوق بُدئ بالأقرب فالأقرب. القرطبي:١٩/٢٧٧.\nما المراد بالرحم؟ وما حقوقهم؟\nفَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ٢٢ أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ٢٣\nقوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ﴾: يقول تعالى ذكره: هؤلاء الذين يفعلون هذا؛ يعني الذين يفسدون ويقطعون الأرحام الذين لعنهم الله، فأبعدهم من رحمته. (فأصمهم): يقول: فسلبهم فَهمَ ما يسمعون بآذانهم من مواعظ الله في تنزيله. ﴿وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ﴾: يقول: وسلبهم عقولهم، فلا يتبينون حجج الله، ولا يتذكرون ما يرون من عبره وأدلته. الطبري:٢٢/ ١٧٨.\nمن الذين لعنهم في هذه الآية؟ وما نتيجة العمى الذي أصاب أبصارهم\nأَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ٢٤\nوكأن القلبَ بمنزلة الباب المُرتَج، الذي قد ضُرِبَ عليه قفل؛ فإنه ما لم يُفتَح القفل لا يمكن فتح الباب والوصول إلى ما وراء، وكذلك ما لم يرفع الختم والقفل عن القلب لم يدخل الإيمان والقرآن. ابن القيم:٢/٤٥٤.\nبيّنت الآية الطريق لفتح قلب الإنسان ودخول الإيمان فيه؛ وضّح ذلك.\nأَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ٢٤\nوالمعنى: أفلا يتفهمونه، فيعلمون بما اشتمل عليه من المواعظ الزاجرة والحجج الظاهرة والبراهين القاطعة، التي تكفي من له فهم وعقل وتزجره عن الكفر بالله والإشراك به والعمل بمعاصيه؟! الشوكاني:٥/٣٨.\nما علامة حصول التدبر من القارئ للقرآن الكريم؟\nإِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ٢٥\nيخبر تعالى عن حالة المرتدين عن الهدى والإيمان على أعقابهم إلى الضلال والكفران؛ ذلك لا عن دليل دلَّهم ولا برهان، وإنَّما هو تسويل من عدوهم الشيطان وتزيين لهم، وإملاء منه لهم. السعدي:٧٨٩.\nما سبب ارتداد بعض المنتسبين للإسلام إلى الكفر؟\nفَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ ٢٧ ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ٢٨\nالجمع بين الإخبار عنهم باتباعهم ما أسخط الله وكراهتهم رضوانه، مع إمكان الاجتزاء بأحدهما عن الآخر للإيماء إلى أن ضرب الملائكة وجوه هؤلاء مناسب لإقبالهم على ما أسخط الله، وأن ضربهم أدبارهم مناسب لكراهتهم رضوانه؛ لأن الكراهة تستلزم الإعراض والإدبار. ابن عاشور:٢٦/١١٩.\nما مناسبة الجمع بين الإخبار عن المشركين باتباعهم ما أسخط الله وكرههم رضوانه من جهة، وضرب الملائكة وجوههم وأدبارهم من جهة أخرى؟"],[510,"§محمد\nwords\nبِسِيمَاهُمعَلاَمَاتِهِمُ الظَّاهِرَةِ.\nلَحنِ القَولِمَا يَبدُو مِن كَلاَمِهِمُ الَّذِي يَدُلُّ عَلَى مَقَاصِدِهِم.\nوَلَنَبلُوَنَّكُملَنَختَبِرَنَّكُم.\nوَشَآقُّواخَالَفُوهُ، وَحَارَبُوهُ.\nيَتِرَكُم أَعمَالَكُميَنقُصَكُم ثَوَابَ أَعمَالِكُم.\nفَيُحفِكُميُلِحَّ عَلَيكُم، وَيُجهِدكُم.\nأَضغَانَكُمأَحقَادَكُم.\ndeeds\nاذكر ثلاثًا من صفات المنافقين جاءت في القرآن الكريم.\nادع الله أن يجعلك من الصابرين.\nأنفق اليوم جزءًا من مصروفك في سبيل الله ولا تبخل به.\nguid\nإيمانك بالقضاء والقدر يقتضي الصبر على البلاء والمصيبة.\nاجعل أعمالك كلها لله وحده ولا تقصد رضى الناس أو مدحهم.\nالمؤمن عزيز بإيمانه فلا يجبن ولا يضعف.\nrefl\nوَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ\nولو نشاء يا محمد لأريناك أشخاصهم فعرفتهم عيانًا، ولكن لم يفعل تعالى ذلك في جميع المنافقين سترًا منه على خلقه، وحملًا للأمور على ظاهر السلامة، وردًا للسرائر إلى عالمها. ابن كثير:٤/١٨٣.\nلماذا لم يبين الله تعالى للمسلمين جميع المنافقين؟\n۞يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ ٣٣\n﴿وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ﴾: يحتمل أربعة معان؛ أحدها: لا تبطلوا أعمالكم بالكفر بعد الإيمان. والثاني: لا تبطلوا حسناتكم بفعل السيئات. والثالث: لا تبطلوا أعمالكم بالرياء والعجب. والرابع: لا تبطلوا أعمالكم بأن تقتطعوها قبل تمامها. ابن جزي:٢/٣٤٣.\nبيّن مبطلات الأعمال من خلال هذه الآية.\nفَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ\n﴿وَٱللَّهُ مَعَكُمۡ﴾: فيه بشارة عظيمة بالنصر والظفر على الأعداء. ابن كثير:٤/١٨٤.\nماذا يترتب على معية الله للمسلمين؟\nفَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ\n﴿فَلَا تَهِنُواْ﴾ أي: لا تضعفوا عن الأعداء. ﴿وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ﴾ أي: المهادنة والمسالمة ووضع القتال بينكم وبين الكفار في حال قوتكم وكثرة عَدَدِكُم وعُدَدِكُم ﴿وَأَنتُمُ ٱلۡأَعۡلَوۡنَ﴾ أي: في حال علوكم على عدوكم، فأما إذا كان الكفار فيهم قوة وكثرة بالنسبة إلى جميع المسلمين، ورأى الإمام في المهادنة والمعاهدة مصلحة فله أن يفعل ذلك. ابن كثير:٤/١٨٤.\nبينت الآية موقف المسلمين من عدوهم في حال قوتهم، فما موقفهم في حال ضعفهم؟\nإِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ٣٦\nالأشبه أن هذا عطف على قوله: ﴿فَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ﴾ تذكيرًا بأن امتثال هذا النهي هو التقوى المحمودة، ولأن الدعاء إلى السلم قد يكون الباعث عليه حبّ إبقاء المال الذي ينفَق في الغزو، فذُكروا هنا بالإيمان والتقوى ليخلعوا عن أنفسهم الوهن؛ لأنهم نُهُوا عنه وعن الدعاء إلى السلم، فكان الكف عن ذلك من التقوى. ابن عاشور:٢٦/١٣٣.\nما علاج الوهن الذي أصاب الأمة من خلال الآية الكريمة؟\nوَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ٣٦\n﴿وَلَا يَسۡـَٔلۡكُمۡ﴾ ربكم (أموالكم) لإيتاء الأجر، بل يأمركم بالإيمان والطاعة ليثيبكم عليها الجنة؛ نظيره قوله: ﴿مَآ أُرِيدُ مِنۡهُم مِّن رِّزۡقٖ﴾ [الذاريات:٥٧]. وقيل: لا يسألكم محمد أموالكم؛ نظيره: ﴿قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍ﴾ [ص: ٨٦]. وقيل: معنى الآية: لا يسألكم الله ورسوله أموالكم كلها في الصدقات، إنَّما يسألانكم غيضًا من فيض -ربع العشر- فطيبوا بها نفسًا. القرطبي:٤/١٦٣.\nمن علامات صدق العالم عدم سؤاله الناس أموالهم، كيف عرفت هذا من الآية؟\nهَٰٓأَنتُمۡ هَٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم ٣٨\n﴿وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ﴾ أي: إنَّما ضرر بخله على نفسه؛ فكأنه بخل على نفسه بالثواب الذي يستحقه بالإنفاق. ﴿وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ﴾ أي: يأت بقوم على خلاف صفتكم، بل راغبين في الإنفاق في سبيل الله. ابن جزي:٢/٣٤٤.\nنستفيد من هذه الآية أن الجزاء من جنس العمل، بين ذلك."],[511,"§الفتح\nwords\nفَتحًا مُبِينًاهُوَ: صُلحُ الحُدَيبِيَةِ عَامَ سِتٍّ مِنَ الهِجرَةِ.\nالسَّكِينَةَالطُّمَأنِينَةَ، وَالثَّبَاتَ.\nظَنَّ السَّوءِالظَّنَّ السَّيِّء؛ وَهُوَ: الظَّنُّ بِأَن لَن يَنصُرَ الله دِينَهُ.\nعَلَيهِم دَائِرَةُ السَّوءِدُعَاءٌ عَلَيهِم بِأَن تَدُورَ عَلَيهِم دَائِرَةُ العَذَابِ، وَكُلُّ مَا يَسُوءُ.\nوَتُعَزِّرُوهُتَنصُرُوا الله.\nوَتُوَقِّرُوهُتُعَظِّمُوا الله.\ndeeds\nصلِّ على النبي محمد -صلى الله عليه وسلم- فإن ذلك من تعزيرك وتوقيرك له.\nطبق سنة من السنن -كالسواك مثلًا- مستحضرًا تعظيم هدي النبي.\nاجعل لك وردًا من التسبيح والأذكار في الصباح والمساء.\nguid\nامتنان الله تعالى على المسلمين بصلح الحديبية.\nأحسن الظن بالله؛ فالله تعالى عند ظن عبده به.\nمن تعظيم النبي ذكر شمائله والصلاة عليه واتباع سنته.\nrefl\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١\nقال الزهري: \"لم يكن فتح أعظم من صلح الحديبية؛ وذلك أن المشركين اختلطوا بالمسلمين فسمعوا كلامهم فتمكن الإسلام في قلوبهم؛ أسلم في ثلاث سنين خلق كثير، وكثر بهم سواد الإسلام\". البغوي:٤/١٦٦.\nكيف كان صلح الحديبية فتحًا ونصرًا؟\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ\nرتب الله على هذا الفتح عدة أمور، فقال: (ليغفر لك الله ماتقدم من ذنبك وما تأخر)؛ وذلك والله أعلم بسبب ما حصل بسببه من الطاعات الكثيرة، والدخول في الدين بكثرة، وبما تحمَّل من تلك الشروط التي لا يصبر عليها إلا أولو العزم من المرسلين. السعدي:٧٩١.\nلماذا رتب الله على الفتحِ مغفرةَ ما تقدم وما تأخر من النبي صلى الله عليه وسلم\nإِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ١ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ٢\nوجمع سبحانه له بين الهدى والنصر؛ لأن هذين الأصلين بهما كمال السعادة والفلاح؛ فإن الهدى هو العلم بالله ودينه، والعمل بمرضاته وطاعته، فهو العلم النافع والعمل الصالح. والنصر: القدرة التامة على تنفيذ دينه بالحجة والبيان والسيف والسنان؛ فهو النصر بالحجة واليد، وقهر قلوب المخالفين له بالحجة، وقهر أبدانهم باليد، وهو سبحانه كثيرًا ما يجمع بين هذين الأصلين؛ إذ بهما تمام الدعوة وظهور دينه على الدين كله. ابن القيم:٢/٤٥٦.\nلماذا جَمَع الله -سبحانه وتعالى- للرسول بين الهدى والنصر في هذه الآيات؟\nلِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ٢\nعن المغيرة بن شعبة قال: كان النبي يصلي حتى تَرِمَ قدماه، فقيل له: أليس قد غفر الله لك ما تقدم من ذنبك وما تأخر؟ قال: «أفلا أكون عبدا شكورا». الشوكاني:٥/٤٦.\nلماذا كان النبي يصلي حتى تَرِمَ قدماه مع أنه غفر له ما تقدم من ذنبه وما تأخر؟\nهُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ٤\nقال الرازي: والسكينة: الثقة بوعد الله، والصبر على حكم الله؛ بل السكينة هاهنا معين يجمع فوزًا وقوة وروحًا، يسكن إليه الخائف ويتسلى به الحزين، وأثر هذه السكينة الوقار والخشوع وظهور الحزم في الأمور. البقاعي:١٨/٢٨٤.\nما أثر السكينة على المؤمن؟\nلِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ\nوالحق الذي لا شك فيه أن الإيمان يزيد وينقص؛ كما عليه أهل السنة والجماعة، وقد دل عليه الوحي من الكتاب والسنة. الشنقيطي:٧/٣٩٤.\nهذه الآية تقرر أمرًا من عقيدة أهل السنة والجماعة فما هو؟\nلِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ\nومعنى التعزير في هذا الموضع: التقوية بالنصرة والمعونة، ولا يكون ذلك إلا بالطاعة والتعظيم والإجلال... فأما التوقير: فهو التعظيم والإجلال والتفخيم. الطبري:٢٢/ ٢٠٨.\nما المراد بالتعزير والتوقير في الآية؟ وكيف يكون ذلك؟"]])